          "Micron의 FY4Q26 매출은 542.3억달러로 전분기 414.6억달러와 전년 동기 113.2억달러를 크게 웃돌았다. 조정 잉여현금흐름은 332.0억달러였고 다음 분기 매출 가이던스는 615억달러±15억달러였다. 매출은 발표 실적, 다음 분기 수치는 회사 전망이다. 메모리 수요가 가격 기대뿐 아니라 큰 현금 유입으로 나타난 분기였다. <a href=\"https://investors.micron.com/news/press-release/2026/Micron-Technology-Inc--Reports-Record-Fiscal-Fourth-Quarter-and-Full-Year-2026-Results/default.aspx\" target=\"_blank\" rel=\"noopener noreferrer\">Micron 공식 실적 발표</a>.",
