          "미래에셋증권 10월 House View는 2027년 DRAM 수요 비트 성장률 +27.6%, 서버 출하 +17%, 서버 DRAM 비트 성장률 +32.1%를 전망했다. 최근 보수적 증설과 공간 제약 때문에 본격적인 생산능력 확충에 시간이 걸린다는 분석이다. 제공 브리핑의 화웨이 스마트폰 원가 상승·추가 가격 인상 계획은 메모리 공급자의 가격 강세가 세트 업체의 비용 부담으로 전달되는 반대편 사례였다.",
          "MLCC·FC-BGA에서는 고사양 제품이 유효 생산능력을 더 소모하는 구조가 제시됐다. 미래에셋증권은 AI용 MLCC 1개 생산이 범용 약 3개분 캐파를 쓰고, 수주/매출 비율 1.6·가동률 95%·유통재고 30일 미만이라고 분석했다. FC-BGA 공급 부족률은 2027년 21.7%, 2028년 32.6%로 전망했다. 이날 삼화콘덴서 +6.4%에는 Murata 초소형 MLCC 양산과 웨어러블 수요도 부각돼 AI 서버 뉴스와 별도 재료가 더해졌다.",
          "삼성전기 분석은 세종·베트남 FC-BGA 증설액 합계 약 6.8조원에 인프라·부지·추가 증설을 포함하면 2026~2028년 기판 투자 9~10조원, MLCC 포함 총 CapEx 14~15조원으로 추정했다. 공시 범위와 증권사가 추가 비용을 포함한 추정 범위는 다르다. 고객사의 CapEx 지원과 가동률 보장, 장기 공급계약이 투자 부담을 나누는 계약 구조로 소개됐다. 신한 ETF 자료도 AI 병목을 메모리·광통신·전력으로 분류했으며, 편입 비중이 높은 상품의 수익률과 시장 전체 수급은 구분할 필요가 있다."
