    "코스피는 7,003.74(+0.46%), 코스닥은 893.29(-0.11%)로 마감했다. 코스피는 기관 3,813억원 순매수와 장 후반 외국인 선물 매수에 힘입어 7,000선을 회복했고, 코스닥은 외국인 1,742억원 순매도로 6거래일 만에 하락했다. 다만 상승·하락 종목은 코스피 500·362개, 코스닥 958·681개로 양 시장 모두 상승 종목이 더 많았다. 전일 급등한 장비주 일부가 쉬는 사이 광통신·정유·방산·배터리로 매수세가 이동했다.",
