        "SAVE 브리핑의 Bloomberg 요약에서는 Broadcom 관련 대주단이 AI 칩·인프라 확보를 위해 총 600억달러 조달에 나섰다고 전했다. 선순위 담보대출 420억달러와 후순위 180억달러로 나뉘며 Blackstone의 자체 펀드 약정은 90억달러였다. 미국 마감 자료의 최대 420억달러 금융지원 보도와 전체 600억달러 패키지는 범위가 다르다. 칩 공급사가 고객의 구매 자금 마련까지 연결하는 금융구조가 구체적으로 등장했다.",
