        "BIS는 2021~2025년 AI 기업 유입 투자금의 55.2%가 다른 AI 기업에서 왔으며, AI 기업 간 투자 중 금액 기준 46.4%는 투자자와 피투자자 사이 상업·공급망 관계도 존재했다고 집계했다. 후자는 전체 AI 투자금의 비율이 아니라 AI→AI 투자라는 부분집합의 비율이다. BIS는 핵심 투입요소 확보 같은 경제적 이유와 함께 이러한 관계의 불투명성·거시 위험을 지적했다. <a href=\"https://www.bis.org/publications/bulletin-137-circular-relationships-among-ai-firms\" target=\"_blank\" rel=\"noopener noreferrer\">BIS Bulletin 137</a>",
        "Anthropic이 이르면 11월 중순 상장을 추진하고 1.8~2조달러 기업가치가 거론된다는 보도도 SAVE에 포함됐다. 상장 일정·가치는 논의 중인 내용이다. 같은 브리핑에서 PIMCO의 Stracke는 최근 실질금리 상승을 AI 생태계 자금 수요로 설명했고, BofA는 분기말 머니마켓 1,180억달러 유출·채권펀드 188억달러 유입, 6년 이상 장기채 74억달러 유입을 제시했다. 금리 상승의 원인에 관한 운용사 견해와 실제 집계된 펀드 흐름은 따로 기록할 내용이었다.",
