      "Tesla 공식 발표는 3분기 생산 46만4,391대·인도 48만6,532대, ESS 배치 13.7GWh였다. Model 3/Y 인도는 47만8,237대, 기타 모델 8,295대였다. 자동차 인도와 ESS 배치는 각각 실물 수요 지표지만 회사는 판매가격·원가·환율 등에 따라 분기 손익이 달라진다고 명시했다. <a href='https://ir.tesla.com/press-release/tesla-third-quarter-2026-production-deliveries-and-deployments' target='_blank' rel='noopener noreferrer'>Tesla 3분기 생산·인도·배치</a>",
