        "국내 정유에서는 S-Oil +3.2%, GS +3.9%, 가스에서는 SK가스 +4.65%였다. 신한·미래에셋은 후티-사우디 교전과 에너지 가격 강세, 계절적 수요를 재료로 설명했다. SAVE에는 원유 수송 회복과 달리 유럽 디젤 선물 강세 및 높은 유조선 운임이 실렸다. 원유 물량 회복만으로 제품 부족과 물류비가 동시에 해소되는 구조는 아니었다.",
        "사용자가 제공한 삼성리서치 정성태 발언은 유가가 내려도 금리가 높게 남는 배경을 재정적자·투자 확대에 따른 채권 공급, 중앙은행의 미국채 수요 공백, 일본 장기금리, 양호한 미국 성장, 전기요금·반도체 등 비유가 물가, 글로벌 긴축과 주식 선호로 나눴다. 이는 요인별 기여도를 추정한 결과가 아니라 장기금리에 대한 전문가 해석이다. 실제 이날 미국 10년물은 소폭 내렸지만 5.2%대였다.",
        "같은 발언은 감가상각을 반영한 미국 순저축률을 약 2%로 언급하고 AI 인프라의 감가상각 확대를 감안하면 2029년 음수에 이를 수 있다고 전망했다. 계산표·차트 원본은 이번 첨부에 없었다. AI 투자가 다른 분야 투자를 구축한다는 주장과 1990년대 투자 확대와의 차이도 제시됐으며, 높은 AI 비용·반도체 가격·병목이 근거였다. 현재 순저축률, 미래 감가상각 전망, 다른 산업 투자 감소의 인과효과는 각각 다른 근거가 필요한 내용이다.",
        "정성태는 AI 투자를 수요 충격으로 보고 금리 인상을 표준 대응으로 설명하되 구조적·경기적 수요인지에 따라 정책 대응이 달라질 수 있다고 했다. 금리 상승이 투자비용을 높인다는 사실과 그 때문에 총물가가 반드시 더 오른다는 주장은 구분했다. 이 발언은 새로운 중앙은행 정책 결정이 아니라 AI 투자·자원 배분·물가의 연결에 대한 견해다.",
        "BEA 공식 발표에서 미국 8월 상품·서비스 무역적자는 1,056억달러로 7월 수정치 928억달러보다 확대됐다. 상품 적자 1,366억달러, 서비스 흑자 310억달러였다. 식전 자료와 SAVE는 AI 자본재·반도체·산업기계 수입을 배경으로 제시했다. 전달 자료의 서로 다른 7월 수치를 섞지 않고 수정 발표 기준으로 기록했다. <a href=\"https://bea.gov/data/intl-trade-investment/international-trade-goods-and-services\" target=\"_blank\" rel=\"noopener noreferrer\">BEA 무역통계</a>",
        "SAVE가 인용한 FT 보도는 SpaceX의 약 400억달러 조달 계획을 은행 100억달러·투자등급 채권 300억달러로 나눠 설명했다. Apollo 주도와 PIMCO 논의, 2027년 거래 예상이 담겼다. 협상·계획 금액이며 조달 완료나 현금 유입액이 아니다. AI·우주 데이터센터의 투자 확대와 함께 차입 규모·조건이 중요한 뉴스로 등장했다.",
        "Blue Owl 관련 보도는 보험사를 직접 인수하기보다 보험 자산운용 위임을 확대하는 전략과 데이터센터 임대 모델을 소개했다. 약 20년 임대계약에서 말기 자산가치를 0으로 놓아도 10~12% 수익률을 목표로 할 수 있다는 설명은 회사의 투자 가정이다. 이미 실현된 수익률이 아니며 임차인의 지급능력·재계약·설비 잔존가치는 별도의 위험이다.",
