  changes:{maintained:["공급사의 호실적과 AI 투자주체의 자본비용은 분리됐다.","국채금리 하락과 개별 차주의 신용 부담이 병존했다."],new:["코스피7일 연속 하락 종료, 두 시장 상승종목 확산.","외국인 코스피 현물9일 만 순매수, 오후 선물·전기전자는 매도.","PPI 상승과 명목 소매판매 증가의 에너지 기여, 바이오·화장품·로봇 반등."]},
  assessment:["투매 뒤 반발 매수는 종가와 시장 폭으로 나타났다. 다만 업종 수급과 현선물의 방향이 달라 전면적인 자금 복귀로 보기는 이르다.","미국에서는 장기채·방어주가 강했고 AI 하드웨어는 약했다. 금리가 내려도 조달과 이익 지속성의 평가가 주가를 갈랐다."],
  implications:["낙폭 자체보다 실제 매수 주체·업종별 이익과 현금회수를 우선한다.","조달·증설·제재 완화 계획은 금융종결·생산·도착 시점까지 구분한다."],
  conclusion:"국내는 넓은 반등으로 한 주를 마쳤지만 외국인 IT 현물과 선물 매도는 남았다. 미국 물가의 비용 부담과 AI 차입자의 신용 경계 속에서도 방어주·우량채 수요가 이어졌다. 금요일 반등의 폭과 다음 거래일의 매수 지속성이 이제 서로 다른 확인 대상이다."
