window.MARKET_LEDGER.daily['2026-10'].push({
 date:'2026-10-19',month:'2026년 10월',createdAt:'2026-10-19',updatedAt:'2026-10-19',
 title:'급락 출발을 뒤집은 저가 매수 — 배터리·바이오 확산과 AI 자본 부담',
 tags:['전약후강','기관매수','배터리·ESS','미국시황','CoreWeave','Nscale','전력망병목','프랑스재정'],
 lead:[
  '코스피는 5,768.01(+1.76%), 코스닥은 808.89(+1.78%)로 마감했다. 미국 AI주 급락의 여파로 코스피가 5,500선을 밑돌며 출발했지만 오전 수급 공방을 거쳐 상승으로 돌아섰다. 코스피 상승·하락 종목은 677·204개, 코스닥은 1,186·469개로 상승 종목이 많았다. 반도체보다 배터리·헬스케어·로봇이 반등의 폭을 넓혔다.',
  '기관은 두 시장에서 순매수했고 외국인은 현물·선물 매도를 이어갔다. 미국에서는 CoreWeave가 목요일 반등 뒤 금요일 다시 급락했고, 주말에는 Microsoft의 Nscale 영국 데이터센터 계약 철회 보도가 나왔다. 국내 주가는 이 악재를 안고도 반등했지만 데이터센터의 전력 연결·자금조달·현금회수 문제 자체가 해소된 날은 아니었다.'
 ],
 report:[
  {no:'02',title:'미국 시황 — AI 신용 불안 재확대, 에너지·방어주로 이동',paragraphs:[
   '16일 미국장은 S&P500 7,659.44(-1.09%), Dow 52,002.41(-0.34%), Nasdaq 종합 26,140.03(-2.15%), Nasdaq100 29,187.55(-2.50%)로 마감했다. 필라델피아 반도체지수는 11,137.29(-3.83%)로 8거래일 연속 하락했다. VIX 종가는 19.99(+21.45%)였으며 장중 22 상회와는 구분된다(미래에셋 10/19 글로벌 마켓 브리핑).',
   'CoreWeave는 61.39달러로 11.91% 하락해 전날 69.69달러·5.94% 반등을 되돌렸다. 신한 Digest에서는 Nebius -12.2%, 키움 주간자료에서는 Micron -5.6%·Meta -3.7%가 제시됐다. 높은 회사채 수익률과 CDS 부담 속에서 공급사의 매출 성장뿐 아니라 투자 고객이 자금을 계속 조달할 수 있는지가 다시 주가의 변수가 됐다.',
   '업종별로는 정보기술 -2.54%, 커뮤니케이션 -2.45%와 에너지 +2.46%, 유틸리티 +1.40%, 필수소비재 +1.31%가 갈렸다. Exxon Mobil +2.55%, Coca-Cola +2.07%, Lockheed Martin +3.65%가 올랐고 HPE는 5.97% 하락했다. 기술주 매도와 방어·에너지 순환매가 함께 나타난 장이었다.',
   '미래에셋 시장호가 기준 2년물은 4.7083%(-2.99bp), 10년물은 5.0728%(+1.48bp), 30년물은 5.4209%(+1.53bp)였다. 주간 장기채 강세와 달리 금요일 하루에는 장기금리가 소폭 올랐다. 유가 급등과 장기물 발행 축소 신호의 부재가 부담이었다는 기관 설명으로, 주식 약세가 매일 같은 크기의 국채 강세로 이어진 것은 아니었다.',
   'WTI 11월물은 101.41달러(+3.51%), Brent 12월물은 109.86달러(+3.72%)로 상승했다. 사우디·후티 충돌, 해협의 선박 피격, 러시아 에너지시설 공격이 공급 경계를 키웠다. 달러인덱스는 101.837(-0.16%)이었다. 이 미국 금요일 결과는 한국 19일의 선행 정보이며, 이미 끝난 한국 16일 반등의 원인으로 소급하지 않는다.'
  ]},
  {no:'03',title:'국내 마감 — 오전 매도 압력을 뒤집었지만 외국인 복귀는 미완',paragraphs:[
   '코스피는 5,488.41(-3.17%)로 출발한 뒤 99.96포인트 상승한 5,768.01로 마쳤다. 코스닥도 773.06(-2.73%)에서 출발해 14.11포인트 오른 808.89로 800선을 회복했다. 연합뉴스 종가와 신한·미래에셋 마감 자료가 같은 방향을 확인한다. <a href="https://www.yna.co.kr/view/AKR20261019130800008" target="_blank" rel="noopener noreferrer">19일 종가</a>.',
   '신한 장중 Radar의 코스피 5,642.0(-0.5%), 코스닥 784.4(-1.3%)는 오전 매도와 저가 매수가 맞서던 구간이었다. 미래에셋 오전 Market View도 두 지수 -1.58%와 외국인 초기 순매수를 기록했다. 오후 종가는 두 시장 모두 상승이므로 오전의 코스닥 약세나 외국인 매수 출발을 최종 마감 판단으로 연장할 수 없다.',
   '신한 마감표의 코스피 현물 수급은 외국인 -365억원, 기관 +5,760억원, 개인 -1조876억원이었다. 코스닥은 외국인 -1,438억원, 기관 +670억원, 개인 +641억원이었다. 코스피에서 외국인 매도 규모가 줄고 기관이 흡수했지만 외국인의 순매수 전환은 아니었다. 표의 투자자 범주 합계는 임의로 맞추지 않았다.',
   '외국인은 선물에서도 순매도 중이라는 신한 마감 설명이 남았다. 오전 선물·프로그램 비차익 매수와 오후까지 지속된 현선물 매도는 시간대가 다르다. 금요일의 외국인 현물 매수 복귀가 월요일 업종 전반의 지속적 자금 유입으로 이어졌다고 말하기는 어려웠다.',
   '그럼에도 상승 종목은 코스피 677개, 코스닥 1,186개로 하락 종목 204개·469개보다 많았다. 반도체 대형주의 소폭 상승을 넘어 배터리·바이오·피지컬 AI로 반등이 퍼졌다. 거래대금은 제공 시장 요약 기준 코스피 17.2조원·코스닥 4.6조원이다. 신한은 RSI 20 하회의 과매도 구간에서 매수세가 우위를 확보했다고 해석했다.',
   '환율은 관측 기준을 나눠 봐야 한다. 제공 시장 스냅샷은 1,331.20원(-6.80원)이지만 뉴스1의 오후 3시30분 주간 종가는 1,330.30원(-1.10원)이었다. 서로 다른 시각·전일 기준을 이어 붙이지 않는다. 원화 강세와 외국인 주식 매도는 이날도 병존했다. <a href="https://www.news1.kr/finance/market-exr/6324741" target="_blank" rel="noopener noreferrer">주간 종가 기준</a>.'
  ]},
  {no:'04',title:'AI 자본 사이클 — 주문의 크기에서 가동·회수 일정으로',paragraphs:[
   'CoreWeave의 금요일 재급락은 목요일의 안도 발언과 주가 반등만으로 신용 문제가 끝나지 않았음을 보여줬다. 키움 주간자료는 회사채 수익률이 13%대에서 15%대로, CDS가 900bp대에서 1,200bp대로 올랐다고 정리했다. 이는 종목·만기·관측시점이 다른 기관 인용 범위이며 회사 전체 이자가 즉시 15%로 바뀌었다거나 실제 부도가 발생했다는 의미는 아니다.',
   '주말에는 Microsoft가 Nscale의 영국 Loughton 데이터센터 계약에서 철수했다는 보도가 이어졌다. 2025년 Nscale 공식 발표의 이 시설 계획은 초기 50MW·약 2만3,000개 GB300, 2027년 1분기 서비스 개시였다. 이번 보도에서는 전력 연결이 2030년대까지 어려울 수 있다는 점이 핵심이었다. <a href="https://www.nscale.com/press-releases/nscale-microsoft-2025" target="_blank" rel="noopener noreferrer">당초 회사 발표</a>.',
   '여기서 문제는 고객의 AI 수요가 사라졌는지와 별개로, 전기가 들어오기 전에 설비·GPU·금융 비용이 발생한다는 점이다. 계약이 있어도 가동이 밀리면 매출과 현금 회수도 늦어질 수 있다. Nscale 측이 대체 전력과 다른 영국 부지를 모색하고 Microsoft와의 다른 계약은 영향이 없다고 설명했다는 보도도 함께 남아 있어, 영국 한 부지의 철회를 전체 글로벌 계약 취소로 확대하지 않는다.',
   '월스파가 인용한 미국 대형 데이터센터 최소 47건의 지연·철회·중단, Bernstein의 계획 중 실현 가능 비중 약35%는 조사·기관 추정이다. 전체 설비투자 중 정확히 65%가 사라진다는 확정값으로 사용할 수 없다. 지연과 영구 취소, 프로젝트 건수와 MW·투자금액도 서로 다른 분모다.',
   'SAVE·TNB가 전한 Anthropic의 Project Northstar는 TPU 약1.5GW를 위한 600억달러 조달 협상이다. 후순위 180억달러 중 Blackstone이 90억달러를 맡고 표면금리10%에 할인·수수료를 더하는 구조, Broadcom 보증 선순위 약420억달러가 거론됐다. 조건은 협상 보도이며 금융종결 공시는 확보되지 않았다. 기존 후순위 8.5% 거래와 위험 순위·만기가 같다고 놓고 차이를 전부 시장금리 탓으로 돌릴 수 없다.',
   '반대편에는 강한 수요와 선투자가 공존했다. SAVE는 Amazon 내부자료 보도를 인용해 GPU 선지급과 전력 연결 대기로 장비가 창고에 머물며 현금이 묶인다고 전했다. AWS 수요·수주잔고 강세와 향후 FCF 적자 전망은 서로 모순이 아닐 수 있다. 다만 비공개 자료의 전망을 회사의 확정 가이던스로 취급하지 않는다.',
   '키움은 이번 빅테크 실적에서 CapEx 상향만큼 FCF와 본업 매출 전환을 중요하게 봤다. Meta의 광고 효율·Muse 초기 성과, Tesla의 ESS 수익성·피지컬 AI 상용화, Lam Research의 신규 증설과 공정 전환 투자 비중이 관찰 대상이다. 공급업체 수주 확대가 단기 매출에는 유리해도 중기 공급 확대를 경계하는 메모리 주가에는 다른 재료가 될 수 있다는 설명이다.'
  ]},
  {no:'05',title:'주도 업종 — ESS·바이오·로봇의 확산, 반도체는 작은 회복',paragraphs:[
   '신한 마감 설명의 삼성전자 +1.2%·SK하이닉스 +0.4%에 비해 삼성SDI +11.7%·LG에너지솔루션 +7.2%의 배터리 상승폭이 컸다. 미래에셋 마감에서는 2차전지소재 ETF +9.11%, 2차전지테마 ETF +7.81%였다. 제공 시장 요약의 삼성SDI +10.9% 등과는 집계 시각이 달라 숫자를 혼합하지 않았다.',
   '중국 ESS 업체의 미국 진출 제약·철수 보도, 북미 ESS 수요와 국내 업체 반사이익 기대가 매수 재료였다. SAVE는 유럽 EV 수요와 내년 실적 반등 기대도 함께 설명했다. 중국 업체 전체가 영구 퇴출됐다는 공식 조치나 국내 기업의 대체 수주 확정으로 확대하지 않으며, 미중 공급망 분절과 실제 계약·이익의 전환은 별도로 본다.',
   '제공 테마 요약에서는 솔루스첨단소재 +20.4%, 에코프로머티 +14.1%, 삼아알미늄 +12.8%, 에코프로 +10.3%로 셀 이외 소재까지 강세가 넓어졌다. 전력 수요 증가에 따른 ESS 기대와 최근 급락 뒤 반발 매수가 겹친 모습이었다. 테마 묶음의 전 종목을 같은 수익 구조로 해석하지는 않는다.',
   '바이오에서는 지투지바이오 +24.7%, 에이비엘바이오 +8.2%, 유한양행 +7.5%가 제공 요약에 나타났다. 미래에셋의 바이오TOP10 +4.37%, 코스닥150 바이오테크 +4.10%도 업종 확산을 보여준다. 신한은 장중 에이비엘바이오의 ESMO 이중항체 데이터 공개를 개별 재료로 언급했다. 방어적 업종 순환과 임상별 결과는 구분한다.',
   '미국 Merck·Moderna의 맞춤형 mRNA 암 백신과 이중항체·ADC 데이터가 ESMO 관심을 모았다. 제공 TNB의 3상·위험비·시장 기대치는 아직 발표 원문과 시점 대조가 필요한 항목이다. 이번 마감 보고서에서는 임상 성공이나 허가 결론을 새로 확정하지 않고 행사·데이터 공개의 관찰 대상으로 남긴다.',
   '현대차 +4.5%, 레인보우로보틱스 약+7%와 로봇 ETF +5.34%는 피지컬 AI 강세를 보여줬다. 현대차그룹 RX 전략 조직과 Atlas 양산·배치 논의, 중국의 체화지능 상용화 정책과 국가표준이 함께 주목받았다. 조직 신설과 계획이 실제 현장 배치·외부 판매·반복 가능한 ROI로 이어지는 시점은 별개다.',
   '정유에서는 신한 마감 기준 S-Oil +1.6%·GS +0.9%가 유가·제품 마진 기대에 올랐다. Apple 폴더블폰 사전예약 보도에 비에이치 +5.4%, SpaceX 공급망 합류 발표에 KBI동양철관 상한가가 별도 재료였다. 제공 요약의 나라스페이스테크놀로지 +14.8% 등 우주항공 강세도 이어졌다.',
   '오전 Market View는 APR의 미국 Costco 약400개 매장 진출, 삼성바이오로직스의 ADC 서비스 역량 소개, 큐리옥스의 4분기 영업 관련 IR 레터를 전했다. 해당 자료의 종목 수익률은 오전 관측값이며 종가로 옮기지 않는다. 중국 CXMT의 분기 이익 성장 둔화 우려 보도도 있었지만 당일 주가 반응만으로 기술 진전·양산 수율·서버 인증을 판정할 수는 없다.'
  ]},
  {no:'06',title:'거시·금리 — 프랑스는 등급보다 조달 경로, 중국은 생산과 내수의 차이',paragraphs:[
   '신한의 프랑스 재정 분석은 2027년 예산안을 둘러싼 정치 교착과 기초재정적자, 이자 부담을 연결했다. 정부 계획 기준 부채비율은 2026년119.3%에서2027년121.7%, 이자비용은2025년647억유로에서2026년792억유로로 늘어나는 경로다. 높은 금리가 신규 발행·차환에 점진적으로 반영돼 예산안 통과만으로 재정 부담이 사라지지 않는다는 설명이었다.',
   '10월1일 발표된 540억유로 건전화 계획의 실제 규모는 의회 협상에 따라 달라질 수 있다. 신한은 49.3조 활용과 불신임 저지의 타협 경로를 기본으로 보고 Moody’s 한 단계 하향, 프랑스-독일10년 스프레드110~140bp를 예상했다. 협상 결렬 시150bp 이상 고착, 실행 가능한 중기 조정 시100bp 부근이라는 범위는 전망이지 당일 확정 가격이나 이미 발생한 등급 변경이 아니다.',
   '이 보고서가 강조한 전달 경로는 등급 하향 즉시 ECB 담보 탈락이라는 기계적 충격보다 국채가격 하락→담보·레포 조건 악화→은행채 조달 비용이었다. 담보 규정의 등급 구간·최고등급 적용과 긴 평균 만기가 직접 충격을 완충할 수 있다는 반론도 포함됐다. ECB TPI 역시 무조건적인 매입 약속이 아니라 재정·부채 지속가능성을 고려하는 조건부 수단이라는 평가다.',
   '중국은 미래에셋 마감 기준 3분기 GDP 전년비4.5%로2분기4.3%보다 높아졌지만 산업생산 개선과 소비·투자 부진의 차이가 남았다. 상해종합3,730.92(+0.39%), 심천성분11,817.42(+0.13%)로 은행 등 대형주가 하단을 지지했다. 홍콩은 중양절 휴장이었으므로 제공 스냅샷의 항셍+0.5%를19일 현물 수익률로 쓰지 않는다.',
   '휴머노이드 국가표준6건의2027년4월 시행 계획, 상무부의 가정·물류 체화지능 상용화 지원과 산업용 로봇 생산 증가가 중국 로봇주의 개별 재료였다. 신한 Econ Check up은 사전에 중국의 수출·생산과 내수 차별화를 경계했으며,19일 GDP 발표를 이전 전망치로 대체하지 않는다.',
   '22일 금통위에 대해 신한은 연속 인상의 효과와 AI 투자 불확실성을 점검하는 동결을 예상했다. 추가 긴축 필요성이 사라졌다는 판단은 아니며 통방문 문구·소수의견이 향후 경로의 관건이다. 일본에서는 우에다의 기조 물가와 인상 속도 발언, 재정 측 국채 발행 관리 설명이 따로 전해졌다. 국채 수급·정책 신뢰와 글로벌 금리 변수를 하나의 원인으로 합치지 않는다.'
  ]},
  {no:'07',title:'에너지·물류·포지션 — 원유 가격과 디젤 병목, 위험선호의 온도 차',paragraphs:[
   '주말 러시아 Petersburg Oil Terminal·Ruchi 저장시설 공격 보도와 중동 선박 피격이 공급 불안을 키웠다. 월요일에는 러시아산 에너지 구매국에 대한 신규 관세 유예 보도로 유가가 일부 되돌렸지만, 제공 스냅샷의 Brent108.65달러(-1.10%)는 금요일 선물 종가109.86달러와 관측시점이 다르다. 제재 완화 기대가 생산·선적·도착 물량의 즉각적인 회복을 뜻하지는 않는다.',
   'TNB가 전한 Goldman Sachs의 Dan Struyven은 걸프 제품 물동량과 러시아 디젤 수출 부진, 전쟁 전부터 타이트했던 정제시장을 구분했다. 원유 가격이 내려도 정제품 가격이 오래 높을 수 있다는 전망이다. 앞서 발표된 IEA의 디젤2,000만배럴 이상 조기 방출은 기존 잔여 비축분 공급 가속과 함께 읽어야 하며 이번 주말에 새로 결정된 방출로 중복 계산하지 않는다.',
   '이란의6~7일 내 해협 재개방 발언은9월부터 제시된 조건부 제안의 재확인이었다. 항만 봉쇄·제재·적대행위 관련 요구가 남아 있어 새로운 종전 합의나 실제 통항 정상화가 아니다. 이집트의 사우디 방위 지원 결정 보도 역시 구체적 병력 규모·파견 시점은 확인되지 않았다.',
   'Centinela에서는700명 이상이 참여한 파업의 종료와 단체협약 승인이 보도됐다. Antofagasta 측은 파업 기간에도 정상 생산을 유지했다고 설명했다. 노사 합의는 차질 위험의 완화 재료지만 실제 생산 손실이 있었다고 전제해 회복 물량을 더해서는 안 된다. 괌 태풍에 따른 항만·공항 폐쇄와 구호물자3~5일 지연 우려도 별도의 지역 물류 뉴스였다.',
   'SAVE가 전한 Goldman Sachs 포지셔닝 분석은 헤지펀드 순레버리지 축소·모멘텀 ETF 유출과 방어적 이동을 설명했다. 반면 Morgan Stanley는 조정 막바지와 우량주 매수 준비를 주장했다. 키움은 과매도를 인정하면서도 AI 신용·FCF 확인 전 높은 변동성을 예상했다. 서로 다른 기관의 시계와 전망을 합쳐 단일한 바닥 확인으로 쓰지 않는다.',
   '주간 Nasdaq100 급락과 미10년물 하락을 근거로 국채 헤지 기능 회복을 읽는 보도는 있었지만, 금요일 하루의 장기금리는 소폭 상승했다. CTA 숏커버도 당시 기관의 설명이지 실제 거래량을 분해한 결과는 아니다. 포지션 경감·업종 순환·기업 현금흐름이 반등의 지속성을 가를 변수로 남았다.'
  ]}
 ],
 watch:['외국인 현물 매도 축소가 순매수·선물·전기전자 복귀로 이어지는지','배터리·바이오·로봇으로 넓어진 시장 폭과 거래대금의 지속성','CoreWeave 채권·CDS와 Nscale 대체 전력·계약 일정','빅테크 실적의 FCF·CapEx·광고 및 AI 서비스 매출 전환','20일 LPR·한국1~20일 수출과22일 금통위의 실제 발표','23일 프랑스 등급 평가와 OAT·은행채·레포 조건','러시아 에너지 제재의 실제 적용 범위와 디젤 공급·해협 통항','GTC Berlin·ESMO 발표 원문과 실제 수주·임상 단계']
});
window.MARKET_LEDGER.dailyAddenda['2026-10-19']={
 changes:{maintained:['AI 주문·공급사 이익과 투자자의 조달·가동·현금회수는 다른 층위였다.','외국인 현물·선물과 업종별 매수의 차이가 남았다.'],new:['미국 금요일 AI주 급락에도 한국은 급락 출발을 뒤집고 두 시장 상승 마감.','기관 양 시장 순매수, 배터리·바이오·로봇 중심 상승종목 확산.','Nscale 영국 계약 철회 보도로 전력망 병목이 실제 계약 실행 문제로 부각.']},
 assessment:['국내는 저가 매수와 기관 수요가 오전 매도 압력을 흡수했다. 다만 외국인 매수 복귀나 반도체 중심 추세 회복이 완성된 것은 아니다.','미국의 AI 신용 부담과 유가 상승은 남았으며 주식·채권 반응도 일간과 주간이 달랐다.'],
 implications:['가격 반등과 시장 폭, 실제 자금 유입을 함께 본다.','계약·조달 규모는 전력 연결·금융종결·가동·현금 지급까지 나눠 평가한다.'],
 conclusion:'두 시장은 2거래일째 반등했고 배터리·헬스케어·로봇으로 상승이 넓어졌다. 그러나 미국 AI 신용 경계와 전력 연결 지연, 외국인 현선물 매도는 남았다. 오늘의 변화는 악재 속 국내 매수 흡수력의 회복이며, AI 자본 사이클 전체의 정상화 확인과는 다르다.'
};

