window.MARKET_LEDGER.daily['2026-10'].push({
 date:'2026-10-20',month:'2026년 10월',createdAt:'2026-10-20',updatedAt:'2026-10-20',
 title:'미국 기술주 반등을 잇지 못한 국내시장 — 이익의 지속기간과 매수 기반을 다시 묻다',
 tags:['미국시황','외국인·기관매도','CoreWeave','AI자본사이클','실적·할인율','금통위프리뷰','공사채수급','중국내수'],
 lead:[
  '코스피는 5,552.74(-3.73%), 코스닥은 781.97(-3.33%)로 마감했다. 전날의 동반 반등을 이어가지 못했고 상승·하락 종목은 코스피 118·773개, 코스닥 310·1,348개로 매도 압력이 넓어졌다. 미국 Nasdaq과 반도체지수가 반등했는데도 국내 외국인·기관의 동반 매도와 반도체·방산 약세가 시장을 눌렀다.',
  '쟁점은 당장의 반도체 이익이 사라졌는가보다 높은 이익을 얼마나 오래 유지할 수 있고 누가 추가 주식을 사는가로 이동했다. CoreWeave는 미국 장 초반 급등을 반납했고 장기금리는 다시 올랐다. 기업 실적에서는 CapEx의 크기뿐 아니라 현금 수익화·금융조달 조건·주주환원 실행을 함께 확인해야 하는 국면이다.'
 ],
 report:[
  {no:'02',title:'미국 시황 — 기술주 저가 매수와 장기금리 반등이 함께 나타났다',paragraphs:[
   '한국 20일장의 선행정보인 미국 19일장은 S&P500 7,690.73(+0.41%), Nasdaq 종합 26,430.88(+1.11%), Dow 51,966.03(-0.07%)로 마감했다. 필라델피아 반도체지수는 11,316.34(+1.61%)로 8거래일 연속 하락을 멈췄고 Russell2000은 0.25% 올랐다. VIX는 18.44(-7.75%)로 낮아졌다(미래에셋 글로벌 마켓 브리핑).',
   '경기소비재 +2.73%, 정보기술 +1.19%와 유틸리티 -1.97%, 부동산 -1.17%, 금융 -0.79%가 엇갈렸다. Amazon +4.98%, Datadog +5.36%, Intel +2.43%가 반등했다. 지수 상승은 위험자산 전체의 균일한 회복이 아니라 최근 매도됐던 일부 기술주에 대한 저가 매수와 업종 재배분이었다.',
   'CoreWeave는 Goldman Sachs의 매수 의견과 차입비용 우려가 과도하다는 평가에 장 초반 약7% 올랐지만 종가는 -0.44%였다. 반도체지수 반등과 신용 문제의 중심에 있던 종목의 반등 실패를 동시에 봐야 한다. 증권사의 긍정적 판단은 실제 신규 자금조달의 완료나 채권·CDS 정상화와 같은 사실이 아니다.',
   '미 국채는 주식과 달리 약세였다. 브리핑의 시장 호가 기준 2년물 4.7719%(+6.36bp), 10년물 5.1397%(+6.69bp), 30년물 5.4673%(+4.64bp)로 올랐다. 프랑스 정세 불안과 유럽 금리 상승, 에너지 부담, 위험회피 완화가 당시 기관이 제시한 배경이다. 각 요인의 기여도를 분해한 결과는 아니며 정책금리 인상 기대 하나로 모든 만기를 설명하지 않는다.',
   '원유는 계약월을 나눠 읽는다. 미래에셋은 WTI 11월물 103.66달러(+2.22%), Brent 12월물 109.55달러를 제시한 반면 월스파는 WTI 12월물 98.54달러(-0.5%)를 전했다. 만기·기준가가 다른 수치를 이어 붙여 같은 WTI가 동시에 급등·하락했다고 쓰지 않는다. 공통된 부담은 높은 연료비와 해상운송 위험이 남았다는 점이다.',
   '미국 반등이 한국 반등을 보장하지 않는 이유도 여기에 있다. 미국에서는 소프트웨어·소비재 등으로 매수가 분산될 수 있지만 국내 지수는 메모리 이익과 글로벌 AI 투자 지속성에 대한 민감도가 높다. 미국 상장 SK하이닉스 ADR의 +4.67%와 다음 한국장의 본주 약세도 관측 시간이 다르다. ADR 교환비율·환율·전환 가능성을 확인하지 않은 가격 차이를 무위험 차익거래로 단정하지 않는다.'
  ]},
  {no:'03',title:'국내 마감 — 기관 매수가 사라지자 반등의 폭도 되돌아갔다',paragraphs:[
   '코스피는 전일보다 215.27p, 코스닥은 26.92p 하락했다. 신한 마감 본문의 코스피 약4% 표현보다 표의 -3.73%를 사용했고 두 기관 마감자료와 종가 보도를 대조했다. 전날 상승 우세였던 시장 폭이 두 시장 모두 하락 우세로 바뀌었다. <a href="https://www.news1.kr/finance/general-stock/6326076" target="_blank" rel="noopener noreferrer">10월20일 종가 보도</a>.',
   '신한 마감표 기준 외국인은 코스피 5,395억원·코스닥 1,864억원, 기관은 각각 1조11억원·1,106억원을 순매도했다. 개인은 각각 9,016억원·2,942억원 순매수였다. 미래에셋의 KRX 기준 코스피 외국인 약5.3천억원·기관 약9.9천억원과는 집계 차이가 있어 출처별로 보존한다. 범주 합계를 맞추기 위한 잔여 수급은 만들지 않는다.',
   '전날 기관이 낙폭을 흡수했던 것과 달리 이날은 외국인 현선물과 프로그램 비차익 매도에 기관 매도까지 겹쳤다는 것이 신한의 설명이다. 개인의 매수는 존재했지만 지수와 시장 폭을 지키지 못했다. 장중 코스피 5,500선 하회 뒤 되돌림도 최종적인 추세 반전과는 구분된다.',
   '미래에셋 마감은 삼성전자 -2.52%, SK하이닉스 -4.15%, 반도체TOP10 ETF -5.0%를 제시했다. 미국 반도체 반등에도 국내 대형주의 할인 압력은 남았다. Solidigm 중복상장 관련 우려가 추가로 거론됐지만 검토·보도 단계의 지배구조 쟁점을 확정된 상장 일정이나 실제 이익 유출로 바꾸어 쓰지는 않는다.',
   '방산 ETF는 9.88% 하락했다. 신한 장중자료는 현대로템의 영업이익 감소와 향후 수주 눈높이 조정을 재료로 제시했다. 장중 현대로템 -13.9%, 한화에어로스페이스 -11.3%를 최종 종가처럼 사용하지 않는다. AI 신용 문제와 별도로 비반도체에서도 실적·기대치 조정이 발생했으므로 시장 전체 낙폭을 CoreWeave 하나에 귀속하기 어렵다.',
   '로봇에서는 HT로보틱스 +7.23%, 삼현 +2.67%, 차이나휴머노이드로봇 ETF +3.73% 등 예외가 있었다. 옵티머스 V3 양산 준비 보도가 재료였으나 준비 완료와 실제 양산·판매·고객 수익성은 다른 단계다. 삼성전기 패키지기판 계약, 비나텍 데이터센터용 슈퍼커패시터, 지투지바이오 플랫폼 평가계약 등 개별 재료도 업종 전체의 반전으로 확대하지 않는다.',
   '장중 원화 강세와 외국인 주식 매도는 병존했다. 오전 환율·사용자 코멘트의 1,325원은 종가가 아니며 이를 하루 전체 환율로 채우지 않는다. 신한이 지적한 예탁금 감소·자사주 매입 종료 임박·반대매매 부담은 매수 기반의 질문이다. 자사주 잔여액과 종료일은 실제 체결·완료 공시 확인 전 기관 추정으로 남긴다.'
  ]},
  {no:'04',title:'반도체의 낮은 배수 — 이익 수준보다 지속기간과 매수 주체가 문제다',paragraphs:[
   '신한 국내전략은 9월23일~10월19일 삼성전자·SK하이닉스 주가가 각각 23.6%·31.4% 하락하는 동안 12개월 선행 EPS는 1.8%·3.3% 높아졌다고 정리했다. 같은 자료의 선행 PER은 3.4배·2.9배다. 주가와 이익 추정치가 반대 방향으로 움직였다는 사실은 현재 컨센서스만으로 주가 하락을 설명하기 어렵다는 뜻이지, 주가가 반드시 틀렸다는 뜻은 아니다.',
   '메모리 현물가격과 공급사 이익의 강세는 투자 고객에게는 비용 상승이다. 고객이 높은 가격을 지급하면서도 AI 서비스 매출과 자금조달을 유지할 수 있어야 공급사의 초과이익이 이어진다. 시장이 현금 회수와 차입 비용을 문제 삼으면 당장 EPS가 올라가더라도 그 이익을 인정하는 기간과 배수는 낮아질 수 있다. 이는 신한의 지속가능성 해석이며 실제 주문 취소 규모가 입증됐다는 의미는 아니다.',
   '수급에서는 외국인 매도를 패시브 ETF 하나로 설명하기 어렵다는 분석이 중요했다. 신한은 연초 이후 코스피 외국인 매도 중 반도체 비중을 약89%로 계산했지만 EWY·EEM·IEMG의 보유 주수와 설정 흐름만으로 최근 대규모 매도가 설명되지 않는다고 봤다. ETF 설정, 한국 거래소의 현물 순매수, 선물 노출은 같은 통계가 아니다.',
   'MSCI Korea의 두 대형주 집중도와 EWY가 따르는 25/50 제한 지수도 구분해야 한다. 분기 정기변경의 집중도 제한을 매일 주가가 움직일 때마다 발생하는 기계적 강제매도로 해석하면 매도 원인을 과대 단순화한다. 헤지펀드 위험 축소·재량 매도·환헤지 등 다른 주체와 경로를 함께 검토해야 한다.',
   '주주환원은 완충 요인이지만 미래의 확정 매수 자금과 같지 않다. 삼성전자의 잔여 환원 재원은 연말 FCF와 선수금 등 조정 항목에 달려 있고, 하이닉스 FCF 컨센서스에 환원율을 적용해 계산한 금액도 이사회가 발표한 추가 배당·매입액이 아니다. 진행 중인 매입의 종료와 새 프로그램 결정 사이에는 수요 공백이 생길 수 있다.',
   '신한이 제시한 2027년 영업이익률 50%·40%·30% 조건의 코스피 6,360·5,460·4,710은 목표지수나 확률 밴드가 아니라 정상화 이익·장부가·과거 ROE와 PBR 관계를 이용한 민감도다. 현재 배수가 과거 관계에서 벗어난 상태라면 신용 할인과 수급이 완화돼야 평균 관계로 돌아갈 수 있다. 회귀식의 숫자만으로 현재 적정가치를 확정하지 않는다.',
   '200일선 하회 이후 과거 24개 선택 표본의 60일 수익률 중앙값은 +0.8%였지만 추가 최대낙폭 중앙값은 -5.7%였다. 표본은 일정 기간 연속 하회 조건을 충족한 사례이며 지금의 하루 시점과 같지 않다. 과매도는 반등 가능성을 만들지만 손실 위험을 제거하지 않는다. 이익 추정 유지, 실제 신규 매수, 신용 안정의 동시 확인이 필요한 이유다.'
  ]},
  {no:'05',title:'AI 신용과 포지셔닝 — 비싼 조달이 투자 제약으로 바뀌는 경로',paragraphs:[
   '신한 글로벌전략은 이번 불안을 수요 붕괴의 확정보다 자본조달 가능성에 대한 재평가로 설명했다. 요구수익률 상승은 프로젝트 가치를 낮추고 차환·증설 자금 확보를 어렵게 할 수 있다. 이로 인해 투자 일정이 밀리면 공급사 매출 기대도 약해져 다시 주가·담보가치·조달 조건을 누르는 자기강화 경로가 가능하다. 현재 산업 전체에서 그 순환이 완성됐다는 증거는 아니다.',
   '19일 미국 CoreWeave의 장 초반 상승과 종가 약세는 가격상 안도와 신용 정상화를 분리해야 한다는 후속 관측이다. 제공 자료의 CoreWeave·Oracle CDS는 기간·출처별 수치가 달랐고 20일 동일시점 실거래 계열은 확보되지 않았다. 전날의 높은 CDS를 오늘 새로 급등한 수치로 반복하지 않으며, 채권 수익률과 회사의 전체 부채 이자율도 동일시하지 않는다.',
   'TNB가 전한 CCC급과 BBB급 스프레드 격차는 취약 차주와 우량 차주의 차별화를 시사한다. 그러나 등급 구성·만기·회수율이 다른 지수의 비율만으로 전면적인 신용경색을 입증할 수 없다. AI 차주의 CDS 거래액 증가도 보험료 수준 상승과는 다른 통계이며 주식 위험을 헤지하려는 거래까지 모두 채권 보유자의 부도 판단으로 볼 수 없다.',
   '헤지펀드 자료에는 10월15일까지 5거래일 IT 롱 포지션 매도가 과거 대비 2.61표준편차였다는 Goldman Sachs 프라임브로커리지 분석이 실렸다. 표본 내 IT 노출은 여전히 높은 편인 반면 전체 순레버리지는 낮아졌다는 점이 함께 제시됐다. 이 값은 매도 금액이나 한국 외국인의 실제 강제청산 비율이 아니다. 총위험 축소와 특정 업종 쏠림이 동시에 존재할 수 있다는 해석이 적절하다.',
   '모멘텀 상품의 시장 대비 부진과 선물 롱 청산 역시 수익성 우려를 증폭할 수 있는 경로다. 다만 Nasdaq 포지션 축소 후에도 순매수가 남았다는 Citi 설명과 KOSPI 숏 쏠림 가능성은 실제 숏스퀴즈 발생과 다르다. 되사야 할 잠재 포지션이 있다는 이유만으로 반등 시점과 크기를 정하지 않는다.',
   '해소 조건은 단순한 CapEx 상향이 아니다. 기존 사업의 현금창출이 투자를 얼마나 충당하는지, 계약이 실제 가동·매출 인식으로 전환되는지, 신규 차입·지분조달이 어떤 가격과 담보 조건으로 성사되는지를 확인해야 한다. 현금 완충이 큰 하이퍼스케일러와 차입 의존도가 높은 네오클라우드를 한 재무구조로 묶으면 위험의 분포를 놓친다.',
   '제공자가 작년 뉴스와 크롤링 오류를 알린 엘리스 IPO 등 관련 기사 묶음은 최신 사건 근거에서 제외했다. 다른 PDF에 같은 기사가 다시 등장한 것만으로 독립 검증된 뉴스가 되지 않는다. 비공개 AI 기업의 희망 기업가치·ARR와 인식 매출, Amazon FCF의 분기·누적 기준처럼 원문 정의가 부족한 숫자도 확정 실적 비교에 사용하지 않았다.'
  ]},
  {no:'06',title:'채권·국내 크레딧 — 위험회피 수혜와 매파적 동결 가능성은 다르다',paragraphs:[
   '한화 FI Weekly는 최근 채권 강세를 주식시장 약세의 상대적 수혜와 외국인 선물 숏커버 측면에서 해석했다. 10월16일 기준 국고3년 3.85%, 10년 4.18%를 제시하고 향후 주간 범위를 각각 3.80~4.00%, 4.13~4.25%로 예상했다. 이 수치는 20일 실제 종가가 아니며 전망 범위도 금리 경로의 확정값이 아니다.',
   '한화는 10월12~16일 외국인의 3년 국채선물 매수를 약6.4만 계약으로 계산했다. 앞서 쌓인 매도 포지션 상당 부분이 이미 되돌려졌다면 이후 매수의 힘은 신규 롱 유입 여부에 달려 있다. 매수 계약 수가 모두 새 투자 자금이라는 해석과는 다르다. 외국인 주식 매도에도 원화가 강했던 점에서 채권 이동 가능성을 읽었지만 동일 투자자의 매도대금 흐름을 추적한 증거는 아니다.',
   '20일 한화 금통위 프리뷰는 22일 기준금리 3.0% 동결과 인상 소수의견 1명을 예상했다. 11월 점도표의 상향 가능성도 전망했다. 강한 수출·주택가격·근원물가 부담 때문에 동결하더라도 완화 신호로 읽기 어렵다는 논리다. 아직 열리지 않은 금통위의 실제 표결이나 점도표로 서술하지 않는다.',
   '주식 변동성 확대가 단기 안전자산 수요를 만들더라도 성장·물가·국채 공급이 자동으로 약해지는 것은 아니다. 미국 19일 장기금리 반등과 국내의 인상 위험은 이 차이를 보여준다. 반대로 금융여건 악화가 실물·물가를 충분히 둔화시키면 채권 강세가 이어질 수 있으므로, 숏커버만으로 금리 하락 전체를 설명하거나 반등을 단정하는 것도 경계한다.',
   '공사채에서는 부도 위험보다 발행과 수요 배분이 핵심이었다. 한화는 올해 공사채 순증 약18.6조원 중 LH가 9.6조원을 차지한다고 분석했다. 은행의 위험가중치와 손실보전 구조 차이로 LH 수요가 다른 AAA 공사채를 구축할 수 있다는 설명이다. LH의 높은 발행액을 곧바로 부도 가능성 상승으로 해석할 사안이 아니다.',
   '신한 Credit Monitor는 9월 전금융권 가계대출 -2.2조원 안에서도 은행 +0.6조원과 비은행 -2.8조원이 달랐다고 정리했다. 주택담보대출 +3.3조원과 기타대출 -5.5조원의 조합이다. 가계 전체 차입 감소와 주택 관련 차입 증가가 병존하므로 은행채 발행 부담 완화 가능성을 주택시장 긴축의 완료와 같은 의미로 읽지 않는다.',
   '6월 말 PF 대출 연체율 4.56%와 전분기 대비 0.09%p 하락도 정리·매각 효과를 포함한다. 신규 취급과 기존 부실 처리가 동시에 진행될 수 있어 연체율 하락만으로 전체 위험의 정상화를 선언할 수 없다. 우량 공사채 수급, 은행채 공급, PF 손실 위험은 서로 다른 채널로 구분한다.'
  ]},
  {no:'07',title:'중국·에너지·정책 — 회복의 구성과 공급의 우회 비용을 나눠 본다',paragraphs:[
   '신한의 중국 지표 분석은 3분기 GDP +4.5%와 9월 산업생산 +5.5%에 비해 소매판매 +1.1%, 누적 고정자산투자 -7.2%, 부동산투자 -20.6%가 약했다고 정리했다. 전자·로봇·반도체 생산과 수출이 내수보다 강한 구성이다. 중국의 성장률 숫자 하나로 글로벌 소비 회복을 일반화하기 어렵다.',
   '소매판매에서도 자동차 제외 +3.9%와 자동차 -21.2%가 달랐다. 청년 고용의 구조적 어려움과 소비자 신용 축소는 내수 회복의 제약으로 볼 수 있지만 제공된 의견만으로 AI가 모든 실업이나 부진의 원인이라고 확정할 수 없다. 지방채 한도 확대 계획도 실제 집행·가계소득 증가와는 시차가 있다.',
   '프랑스에서는 19일 정세 불안 속 국채금리와 독일 대비 스프레드가 확대됐다는 보도가 있었다. 월스파는 10년물 약4.94%, 30년물 5.94%와 10년 스프레드 140~145bp를 제시했다. 20일 자료의 약150bp와는 관측일을 구분한다. 미국 금리만이 아니라 역내 재정·정치 위험도 글로벌 할인율에 영향을 줄 수 있다는 배경이며, 향후 신용등급 평가 결과를 미리 채우지 않는다.',
   '에너지에서는 러시아 제재 유예에 따른 공급 기대와 사우디 인프라 공격·해상보험 부담이 반대 방향으로 작용했다. 사우디 FII 행사의 2027년 연기는 안전 우려의 신호이지 그 자체로 원유 생산능력 상실은 아니다. 북극항로 원유 약2,000만배럴은 올해 7월~10월 중순, 비교값 약1,300만배럴은 작년 전체 운항시즌이어서 동일 기간 증가율로 단정하지 않는다.',
   '구리는 LME 가용재고 약14만7,450톤과 미국 창고 유입, Centinela 파업 종료로 단기 공급 우려가 일부 완화됐다는 Reuters 재인용이 있었다. 기업은 파업 기간에도 정상 생산을 유지했다고 설명했다. 따라서 합의 뒤 실제 손실 생산량이 복구됐다고 가상의 추가 공급을 더하지 않는다.',
   '미 DHS의 DeepSeek 조달 제외·시스템 제거 고시는 연방 민간기관과 해당 구현을 쓴 제3자 제품까지를 대상으로 한다. 19일 제출·20일 게재와 이전 명령 발령을 구분하며 미국 민간기업 전체의 사용 금지로 확대하지 않는다. <a href="https://public-inspection.federalregister.gov/2026-21447.pdf" target="_blank" rel="noopener noreferrer">연방관보 공식 고시</a>. 이 정책은 규제 범위를 확인한 참고 재료로 반영하고 독립적인 시장 충격이 확인된 새 사건으로 편입하지 않았다.'
  ]}
 ],
 watch:['외국인 현물·선물과 기관 매도, 시장 폭의 동반 안정 여부','CoreWeave 채권·CDS의 동일시점 변화와 실제 신규 금융조달','Meta 등 실적의 본업 현금흐름·CapEx·차입 의존도','반도체 EPS의 유지 여부와 고객 투자·계약 이행 조건','자사주 매입 완료 공시와 새로운 주주환원 결정의 구분','22일 금통위 실제 표결·향후 인상 신호와 국채선물 신규 롱','프랑스 국채 스프레드·23일 등급 평가의 실제 결과','Brent·정제품·해상운송 비용과 중국 생산·소비의 괴리']
});
window.MARKET_LEDGER.dailyAddenda['2026-10-20']={
 changes:{maintained:['AI 수요와 공급사 이익의 강세만으로 고객 자금조달·현금 회수가 보장되지는 않았다.','주가 반등·수급 복귀·신용 안정은 별도로 확인해야 했다.'],new:['미국 Nasdaq·SOX 반등에도 한국은 외국인·기관 동반 매도로 하락 재개.','CoreWeave의 장 초반 급등이 종가 약세로 바뀌며 안도 지속 실패.','금통위 동결 전망 속 인상 위험과 공사채 수요 구축 문제 부각.']},
 assessment:['국내 하락은 반도체 지속이익 할인과 매수 주체의 약화, 방산 등 개별 실적 기대 조정이 겹친 결과로 해석한다. 한 차주의 신용 위험에 낙폭 전체를 귀속하지 않는다.','메모리 이익 추정이 아직 높다는 점은 반론이지만 낮은 PER 자체는 바닥 확인이 아니다. 미국에서는 기술주와 장기금리가 함께 반등해 단순한 전면 위험회피와도 달랐다.'],
 implications:['주식은 이익의 크기·지속기간·자사주를 제외한 신규 수요를 함께 본다.','채권은 안전자산 수요·숏커버와 정책·공급 위험을 분리한다. AI 차주는 금융종결과 실제 현금창출을 확인한다.'],
 conclusion:'미국의 기술주 저가 매수는 국내 반등으로 연결되지 못했다. 외국인·기관의 매도와 반도체·방산 약세로 시장 폭이 다시 악화됐으며, 현재 이익보다 이익의 지속성과 매수 기반이 쟁점이었다. 신용·실적·정책의 확인 없이 하루 반등이나 낮은 배수만으로 국면 전환을 단정하기 어렵다.'
};

/* 2026-10-21 · written 10/22 from the 10/21 information set; earlier entries unchanged. */
window.MARKET_LEDGER.daily['2026-10'].push({
 date:'2026-10-21',month:'2026년 10월',createdAt:'2026-10-22',updatedAt:'2026-10-22',
 title:'수익화 증거에 돌아온 반도체 매수 — 지수 반등과 시장 폭의 간극',
 tags:['미국시황','AI수익화','외국인매수','수출호조','기판·패키징','AIDC실행조건','CATL마진','시장폭'],
 lead:[
  '코스피는 5,735.66(+3.29%), 코스닥은 792.76(+1.38%)로 전날 급락에서 반등했다. 미국 정규장에서 기술주가 약했던 것과 달리 장후 SpaceX 실적과 Supermicro 잠정 매출 상향이 AI 수익성 우려를 일부 덜었다. 국내에서는 수출 호조와 외국인의 코스피 현물 매수가 반도체 대형주를 지지했다.',
  '다만 코스피 상승·하락 종목은 372·490개로 하락 종목이 더 많았고 코스닥은 장중 800선을 회복했다가 792대로 밀렸다. 오늘 확인된 것은 AI 투자의 매출·이익 전환에 시장이 반응한다는 점이다. 산업 전체의 자금조달 정상화나 폭넓은 추세 회복까지 확인된 것은 아니다.'
 ],
 report:[
  {no:'02',title:'미국 시황 — 정규장은 가치주 순환, AI 안도는 장후에 더해졌다',paragraphs:[
   '미국 20일 정규장은 Dow 52,495.88(+1.02%), S&P500 7,712.57(+0.28%), Nasdaq 종합 26,424.81(-0.02%)로 마감했다. Russell2000은 1.65% 올랐지만 필라델피아 반도체지수는 11,283.81(-0.29%)로 다시 소폭 하락했다. VIX는 17.13(-6.13%)였다(미래에셋 글로벌 브리핑).',
   '헬스케어 +2.33%, 부동산 +1.69%, 유틸리티 +1.15%, 금융 +1.12%와 정보기술 -0.34%, 커뮤니케이션 -0.89%가 갈렸다. 대형 AI주에 대한 경계가 남아도 다른 업종이 지수를 지탱하는 순환이었다. Nasdaq 약보합을 미국 위험자산 전체의 약세로, Dow 상승을 AI 우려 해소로 읽으면 두 흐름을 모두 놓친다.',
   '미 국채 시장 호가는 2년물 4.7761%(+0.42bp), 10년물 5.1085%(-3.12bp), 30년물 5.4198%(-4.75bp)로 만기별 방향이 달랐다. 유가 하락과 주택지표 부진, 기술주 위험회피가 장기물에 우호적이었다는 기관 해석이다. 할인율 완화가 부동산·유틸리티를 돕는 경로는 가능하지만 업종 수익률을 금리 효과만으로 분해한 결과는 아니다.',
   '실적에서는 3M +5.78%, Northrop Grumman +4.57%, Equifax +11.33%가 올랐다. 반면 GM은 예상보다 좋은 분기 실적에도 연간 전망 범위 조정과 원가 부담에 6.84% 하락했다. GE 역시 현금흐름 부담이 거론됐다. 시장이 매출·EPS의 상회 여부만큼 향후 비용과 현금 전환을 따지고 있다는 차별화다.',
   '정규장에서는 Meta -1.59%, SpaceX -0.11%였고 신한 자료의 CoreWeave는 약1.7% 상승했다. 이후 SpaceX 호실적과 Supermicro 매출 상향이 시간외 AI주를 지지했다. 이 장후 정보를 미국 20일 정규장 상승 원인으로 소급하지 않고 한국 21일장의 선행변수로 귀속한다.',
   'SpaceX 시간외 상승률은 제공 자료에서 약4.7~8.1%, Supermicro는 약11.3~15.6%로 관측 시점이 달랐다. 정규장과 합성한 하루 수익률로 사용하지 않는다. Netflix도 정규장 약1.7% 하락과 실적 후 추가 하락을 구분한다. 장후의 방향 전환이 다음 정규장에도 유지될지는 당시 아직 알 수 없었다.'
  ]},
  {no:'03',title:'국내 마감 — 외국인이 대형주를 샀지만 반등은 고르게 퍼지지 않았다',paragraphs:[
   '코스피는 182.92p, 코스닥은 10.79p 상승했다. 신한 마감표와 미래에셋 마감이 같은 종가를 제시했고 종가 보도도 일치했다. 코스피 매수 사이드카가 발동되는 등 오전 반등은 강했지만 장 후반에는 상승폭이 줄었다. <a href="https://www.fnnews.com/news/202610211537311135" target="_blank" rel="noopener noreferrer">10월21일 종가 보도</a>.',
   '신한 표 기준 코스피 외국인은 6,649억원 순매수, 기관은 715억원 순매도, 개인은 1조1,319억원 순매도였다. 코스닥에서는 외국인 -1,717억원, 기관 +1,047억원, 개인 +516억원이었다. 코스피 외국인 복귀와 기관의 코스닥 매수를 구분해야 하며 외국인이 두 시장을 모두 샀다고 요약할 수 없다.',
   '코스피 상승·하락 종목 372·490개는 지수 급등과 내부 시장의 온도 차이를 보여준다. 코스닥의 832·802개도 상승 우세가 크지 않았다. 큰 종목의 회복은 지수 위험을 줄였지만 중소형주 전반의 수요를 복구하지는 못했다. 전날의 전면적 하락에서 벗어난 점과 추세 회복의 미완성은 동시에 성립한다.',
   '신한 마감 설명의 삼성전자 +5.7%, SK하이닉스 +5.8%가 지수 반등을 이끌었고 미래에셋의 반도체TOP10 ETF는 4.57% 올랐다. 코스피 현물·프로그램 비차익 매수와 선물 매도 축소가 반등의 수급 경로였다. 선물 매도 축소는 신규 선물 순매수와 다른 표현이며 확인하지 않은 최종 계약 수는 채우지 않는다.',
   'LS ELECTRIC의 분기 최대 실적과 영업이익 증가가 전력기기 심리를 도왔고, 우주항공에서는 미국 실적 안도가 국내 테마로 이어졌다. 바이오는 패스트트랙 지정·특허 등 개별 재료가 더해졌다. 개발 지원 지정과 판매 허가, 특허 등록과 상업 매출은 서로 다른 단계다. 지수 반등 속에서도 개별 실적·정책 위험은 남았다.',
   '방산에서는 LIG디펜스앤에어로스페이스 입찰 제한 관련 불확실성이 부담이었다. 신한 본문 -9.0%, 미래에셋 -10.13%, 장중 -14.2%처럼 관측값이 달라 정확한 종가를 임의 통합하지 않았다. 제한 대상·기존 수주·집행정지 여부가 실제 이익 영향의 크기를 결정하므로 모든 방산업체의 수요 감소로 확대하지 않는다.',
   '달러·원 주간 종가는 종가 보도 기준 1,325.2원으로 전일보다 2.9원 낮아졌다. 장중 1,327.4원이나 아침 자료의 전거래일 수치와는 구분된다. 원화 강세는 외화 비용을 덜 수 있지만 수출기업의 원화 환산 실적에는 반대 영향을 줄 수 있다. 하이닉스 자사주 매입 종료는 기관 마감 인용이며 향후 추가 환원은 아직 전망이다.'
  ]},
  {no:'04',title:'AI 실적의 안도와 한계 — 영업 흑자는 투자 재원 자립과 같지 않다',paragraphs:[
   'SpaceX 공식 공시는 분기 매출 145.75억달러, 영업이익 27.91억달러, SI 매출 75.60억달러(+830%)·영업이익 4.31억달러를 제시했다. CapEx 195.93억달러는 분기 수치다. 제공 기업분석의 SI +538%·연간 CapEx 표기는 공식 표와 달라 채택하지 않았다. <a href="https://www.sec.gov/Archives/edgar/data/1181412/000162828026066482/spaceexplorationtechnologi.htm" target="_blank" rel="noopener noreferrer">SpaceX 공식 실적 공시</a>.',
   '같은 공시의 1~9월 영업현금흐름은 130.97억달러, 유형자산 취득은 480.69억달러였다. 단순 차감은 -349.72억달러로, 분기 영업 흑자만으로 올해 투자가 내부 현금으로 충당됐다고 볼 수 없다. 분기 손익과 누적 현금흐름의 기간도 다르다. 장래 회수기간 목표는 현재 실현된 수익률이 아니다.',
   '그럼에도 주가가 안도한 이유는 최근 시장의 질문에 맞는 정보가 나왔기 때문이다. AI 투자가 주문만 늘리는지, 가동된 설비가 매출과 이익을 만들 수 있는지가 쟁점이었고 이번 자료는 수익화 가능성의 반론을 제공했다. 모든 차주의 대출 조건이 좋아졌다는 증거가 아니라 비관적 가정 일부를 재평가할 단서였다.',
   'Supermicro는 FY2027 1분기 잠정 매출을 185~195억달러로 제시해 종전 145~155억달러를 웃돌았다. 매출총이익률 예상도 10.4~10.8%에서 12.0~12.5%로 높였다. 고객·제품 구성의 개선이 반영됐지만 잠정 발표이고 확정 감사 실적은 아니다. <a href="https://www.sec.gov/Archives/edgar/data/1375365/000137536526000025/smcifirstquarterfy2027busi.htm" target="_blank" rel="noopener noreferrer">Supermicro 공식 잠정 발표</a>.',
   '서버 공급사의 매출 개선은 AI 투자 고객의 최종 수익률과 동일하지 않다. 공급사는 장비를 인도할 때 매출을 얻지만 고객은 장기간 서비스 대금을 받아 투자비를 회수한다. 고객의 차입 만기·금리와 실제 가동 일정이 맞지 않으면 공급사 호실적과 차주의 신용 부담이 병존할 수 있다.',
   'Meta·Oracle·CoreWeave의 CDS 관련 보도는 그 반대편을 보여준다. 제공 TNB의 미국 화요일 관측은 Meta 약112bp, Oracle 약320bp, CoreWeave 약1,082bp였다. 실거래 원시계열과 동일시점 검증은 확보하지 못했으므로 새 고점이나 당일 추가 급등으로 단정하지 않는다. 주식 안도와 보험료 부담의 동시 존재가 핵심이다.',
   '후속 실적의 기준은 CapEx 상향만이 아니다. 본업 매출·현금창출, 선금과 계약대금 회수, 조달 완료와 차환 조건, 가동 전 비용을 함께 봐야 한다. 현금 완충이 큰 기업과 차입 의존형 네오클라우드를 구분해야 산업 전체의 수요 붕괴나 정상화를 성급히 선언하지 않을 수 있다.'
  ]},
  {no:'05',title:'수출과 기판 — 좋은 실적의 규모보다 구성과 이익 시차를 본다',paragraphs:[
   '관세청 공식 검색 표시의 10월1~20일 수출은 616.12억달러로 전년 대비 105.4% 증가했다. 조업일수는 10.5일에서 13.0일로 늘었다. 총액 성장에는 영업일 효과가 포함되므로 전체 증가율을 그대로 일평균 성장으로 쓸 수 없다. 반도체 +222.5%는 신한 마감과 사용자 제공 분석에서 제시됐다. <a href="https://www2.customs.go.kr/" target="_blank" rel="noopener noreferrer">관세청 통관실적</a>.',
   '수출은 실물 수요·가격 강세의 근거였지만 주식의 가격은 그 강세가 얼마나 지속될지를 함께 반영한다. 가격과 제품 믹스, 물량을 나눠야 매출 증가가 최종 수요 확대인지 공급 부족에 따른 단가 상승인지 판단할 수 있다. 10월 전체 약80% 증가라는 전문가 전망도 아직 월간 확정 실적은 아니다.',
   '신한의 대만 분석은 한국과 대만을 같은 AI 베타로 묶지 않았다. 대만은 파운드리·첨단 패키징·기판·네트워킹·서버 ODM까지 연결돼 GPU와 자체 ASIC의 병행 확대를 흡수할 수 있다는 설명이다. 국가별 주가 차이는 업종 범위와 이익 성장 시차를 반영할 수 있으며, 이 해석이 모든 대만 기업의 동일한 수혜를 뜻하지는 않는다.',
   '메모리는 이미 높은 마진을 실현해 정상화 위험이 쟁점인 반면 일부 패키징·기판 기업은 신규 설비 가동과 고부가 제품 비중 확대가 앞으로의 이익 레버리지를 만들 수 있다. 다만 2028년까지의 부족률·매출 목표는 기관 추정과 기업 계획이다. 고객 투자 위축이나 경쟁 증설이 달라지면 그 시차도 바뀐다.',
   '기판 Cycle Again 자료는 수주잔고·가동률·ASP의 동반 개선과 신규 공급 시차를 강조했다. 월평균 PCB 수출액 증가에 비해 중량 증가는 작고 무게당 가격 상승이 컸다는 점은 고부가 믹스의 근거로 제시됐다. 그러나 무게당 가격이 개별 제품의 계약단가나 영업이익률 자체는 아니며 원가와 수율을 함께 확인해야 한다.',
   '21일 저녁에는 삼성전기·Nvidia가 세종·부산 전용 생산시설 공동투자와 다년 기판 공급을 발표했다. 공식 발표로 협력은 확인되지만 당일 한국 종가 이후 정보이므로 낮 반등의 원인으로 소급하지 않는다. 예상 물량 성장과 실제 설비 가동·매출 인식도 분리한다. <a href="https://www.samsungsem.com/kr/newsroom/news/view.do?id=10613" target="_blank" rel="noopener noreferrer">삼성전기 공식 발표</a>.'
  ]},
  {no:'06',title:'국내 AIDC — 발표 용량이 아니라 수요·전력·자금의 결합이 실적을 만든다',paragraphs:[
   '신한 건설·통신·전력·철강 공동 보고서는 국내 AIDC 개발계획 8.4GW와 현시점 추진 가시성이 높다고 판단한 1.5GW를 구분했다. 뒤의 수치는 울산 초기 0.1GW, 동해 1단계 1.2GW, 네이버 0.2GW에 대한 기관 평가다. 나머지 계획이 확정 취소됐다는 뜻이 아니라 네 가지 실행 조건을 더 확인해야 한다는 시나리오다.',
   '첫 조건은 실제 연산 수요다. 보고서는 2030년까지 국내 신규 수요를 최대1GW로 추정해 전체 계획에는 해외 워크로드 유치가 필요하다고 봤다. GPU 수량을 전력 수요로 바꾸는 계산은 가동률·서버 구성·냉각·PUE 가정에 민감하다. 발표된 GPU 확보량이나 수전 용량을 이미 판매된 연산 서비스로 환산할 수 없다.',
   '앵커 테넌트는 수요와 금융을 잇는 연결고리다. 장기 임차인이 확보돼야 예상 임대료를 근거로 차입을 구성할 수 있고, 그 자금이 있어야 착공과 장비 주문이 진행된다. 다만 계약이 있어도 전력 접속과 인허가가 늦어지면 가동 전 비용이 쌓인다. 수요·조달·테넌트·물리적 인프라를 개별 뉴스가 아닌 결합 조건으로 봐야 한다.',
   '이 때문에 업종별 수혜 시점도 다르다. 건설은 착공·공정 진행에서, 통신은 실제 가동과 고객 유치 뒤에서, 발전·PPA 사업은 전력 계약과 공급 구조에서 현금이 발생한다. 같은 GW 계획을 여러 업종의 매출에 중복 합산하지 않는다. 철강처럼 인식 시점은 빠르지만 기존 실적 대비 기여도가 작은 업종도 있다.',
   '전력망에는 별도의 재원 제약이 있다. 보고서는 한전 사채발행 한도와 투자비·재원 격차를 후속 확장의 변수로 봤다. 발전설비가 존재해도 필요한 지역으로 전기를 보내지 못하면 데이터센터 계획은 지연될 수 있다. 신규 한전망 투자 의존도가 낮은 초기 사업과 광역망 보강이 필요한 후속 사업은 실행 위험이 다르다.',
   '통신사의 데이터센터 투자는 주주환원과도 경쟁한다. ESG 자료는 본업의 안정적 영업현금에 비해 GW급 사업의 지분투자 부담이 크므로 향후 FCF가 자사주보다 신규 사업에 배분될 수 있다고 봤다. PF 비중이 높더라도 자기자본과 보증 부담이 없어지는 것은 아니다. 이미 정한 최소 배당과 조건부 자사주, 새 사업의 기대수익을 구분해야 한다.',
   'K-GX의 10년 재정·금융 지원계획도 수요의 배경이지 당장 집행된 순재정 지출은 아니다. 재생에너지 목표만큼 송전망·ESS·인허가·예산 확정이 중요하다. 전력기기에는 현재 주문으로 연결되는 기회가 있을 수 있지만 다배출 업종에는 투자가 먼저 발생하고 회수는 더 늦다. 정책 총액을 모든 관련주의 즉시 이익으로 환산하지 않는다.'
  ]},
  {no:'07',title:'CATL·에너지·장후 뉴스 — 성장과 수익성, 기대와 실행을 분리한다',paragraphs:[
   '중국은 AI 안도로 상승 출발했지만 CATL 실적 충격과 전기차 밸류체인 약세로 하락 전환했다. 미래에셋 마감의 상해종합은 3,713.03(-0.60%), 심천성분은 11,704.35(-0.82%)였다. 한국 반도체 반등과 중국 배터리 약세가 같은 날 나타난 것은 성장 테마가 같아도 실적 구성과 가격 협상력이 다름을 보여준다.',
   '사용자 CATL 해설은 3분기 매출 약1,652억위안(+58.6%)에도 순이익 약212억위안(+14.5%)과 매출총이익률 약20.7%가 기대에 못 미쳤다고 설명했다. A·H주 장중10% 이상 하락은 종가와 구분한다. 공식 분기 공시의 전체 비용·세금 분해는 확보하지 못했으므로 구체 수치는 제공 분석의 인용 범위다.',
   '중국 NEV 배터리 탑재 점유율 상승과 마진 악화는 모순이 아니다. 가격을 양보해 점유율을 지키거나 원재료 상승을 고객에 넘기지 못하면 출하 증가가 같은 비율의 이익으로 이어지지 않는다. 완성차의 공급처 다변화와 자체 배터리 전략은 협상력을 바꿀 수 있지만 당기 마진 하락의 정확한 기여도는 별도 검증이 필요하다.',
   'JPMorgan의 중립 하향과 수요 전망은 기관 판단이다. 전기차·ESS 수요가 강하더라도 배터리 기업이 그 수익을 얼마나 확보하는지는 다른 질문이다. CATL의 강한 기술·현금 기반은 경쟁력 붕괴라는 해석의 반론이며, 중국 업체의 이익 압박이 한국 업체의 자동적인 반사이익을 보장하지도 않는다.',
   '미·이란 중재 보도는 유가와 장기금리 부담을 일부 덜었다. 카타르·파키스탄 제안에서 이자 지급과 동결자금 해제 등 조건이 달라졌고 공식 양국 확인도 없었다. 이를 휴전 체결·사찰 완료·실제 자금 반환으로 바꾸지 않는다. 높은 정제품·운송 비용은 원유 선물의 단기 하락과 별개로 남을 수 있다.',
   '화학 자료는 고가 원료 투입의 역래깅 해소와 산업 수급 회복을 구분했다. 중국 증설이 아시아 폐쇄를 웃돌면 원료 가격 안정만으로 스프레드가 지속 개선되기 어렵다. 재고평가 환입과 본업 수익성, 정유의 제품 부족과 석유화학의 공급과잉을 하나의 유가 수혜로 묶지 않는다.',
   'Firmus 지원 논의·NextDC 전력 지연·프랑스 국채 위험은 중요한 참고 보도지만 이번 자료만으로 새 독립 Casebook 사건으로 늘리지 않았다. AI 생산성 설문도 기업 사용률과 지출 집중, 미래 기대를 담은 자료이지 경제 전체의 실현 생산성 인과효과는 아니다. 영국 Nscale은 기존의 참고자료 분류를 유지한다. 21일 저녁 발표와 앞으로의 실적·통화정책 결과는 낮 시장과 구분해 다음 관측으로 이어간다.'
  ]}
 ],
 watch:['코스피 외국인 현물 매수의 지속성과 코스닥·선물로의 확산','대형주 반등이 코스피 상승종목 비율 개선으로 이어지는지','Meta 등 실적의 본업 현금흐름·CapEx·실제 차환 조건','AI 공급사 매출과 투자 고객의 회수기간·조달 비용의 차이','반도체 수출의 가격·물량·조업일수 분해와 주주환원 공시','삼성전기 장후 발표의 생산능력·납기·투자비 분담','CATL 공식 분기표·가격 협상력과 중국 EV 밸류체인 마진','금통위 공식 일정·결정과 미·이란 공식 발표, 정제품·운송비']
});
window.MARKET_LEDGER.dailyAddenda['2026-10-21']={
 changes:{maintained:['AI 실적과 고객의 투자 재원·자금조달은 구분해야 했다.','낮은 배수·큰 지수 상승만으로 시장 전반의 추세 회복을 확인할 수는 없다.'],new:['미국 장후 실적·잠정 발표와 수출 호조가 국내 반도체 안도로 연결.','외국인은 코스피 현물을 샀지만 코스닥 매도는 지속, 코스피 하락종목 우세.','공식 공시로 SpaceX SI 성장률·분기 CapEx 정의를 확인하고 누적 현금 부담도 함께 점검.']},
 assessment:['수익화 증거가 나왔을 때 매수 반응이 컸다는 점은 전면적인 AI 수요 붕괴론의 반론이다. 다만 실적 개선과 전체 산업의 조달 정상화는 다르다.','한국 지수는 회복됐지만 시장 폭과 외국인 수급은 비대칭이었다. CATL은 수량 성장과 이익 성장의 차이를 보여주는 별도 반례다.'],
 implications:['가격 회복은 실제 신규 매수·시장 폭·신용과 함께 확인한다.','데이터센터는 수요·테넌트·자금·전력을 결합해 보고 기업 손익과 현금흐름의 기간을 맞춰 비교한다.'],
 conclusion:'반도체 대형주와 외국인 코스피 매수가 지수를 끌어올렸다. AI 수익화의 긍정적 단서가 생겼지만 코스피의 하락종목 우세와 지속되는 투자 현금 부담도 남았다. 오늘은 비관의 일부가 완화된 날이며 시장 전반의 수급·신용 정상화가 완성된 날은 아니다.'
};

