window.MARKET_LEDGER.daily['2026-10'].push({
 date:'2026-10-22',month:'2026년 10월',createdAt:'2026-10-23',updatedAt:'2026-10-23',
 title:'실적 안도를 되돌린 현금의 질문 — 램리서치 공급 제약과 메타 투자 부담',
 tags:['미국시황','램리서치','메타FCF','금통위동결','반도체재하락','건설·주주환원','한전크레딧'],
 lead:[
  '코스피는 5,533.77(-3.52%), 코스닥은 764.10(-3.62%)로 전날 반등을 반납했다. 미국 21일 정규장에서는 AI 실적 안도가 이어졌지만 장후 메타·램리서치 발표가 다시 투자비 회수와 이익 기대를 시험했다. 한국은 이 장후 정보를 먼저 반영했고 5,500선 지지력을 점검했다.',
  '금통위는 기준금리 3.00%를 만장일치로 유지했다. 그러나 동결은 인상 사이클 종료 선언이 아니었고 실적 불안까지 해소하지 못했다. 건설의 현금 환원·개별 인프라 계약과 반도체·배터리 약세가 갈린 날이었다. 미국 22일 본장 급락은 아직 이 보고서의 국내 마감 원인에 포함하지 않는다.'
 ],
 report:[
  {no:'02',title:'미국 시황 — 21일의 기술주 회복 뒤 장후 검증이 시작됐다',paragraphs:[
   '미국21일 Dow 52,856.09(+0.69%), S&P500 7,757.16(+0.58%), Nasdaq 26,702.86(+1.05%)로 마감했다. SOX는 11,505.56(+1.97%), VIX는 16.66(-3.76%)였다. 한국22일의 선행정보는 이 정규장과 이후 장후 발표다(미래에셋 브리핑).',
   'SpaceX +7.79%, Supermicro +9.6%, Dell +5.27%로 전날 장후 호재가 본장에도 이어졌다. IT업종은1.61% 올랐지만 커뮤니케이션은1.34% 하락했다. 같은 AI 안에서도 공급사 실적과 플랫폼 비용에 대한 시선이 달랐다.',
   'Netflix는 좋은 분기 숫자보다 다음 분기 전망의 부족이 부각돼5.31% 내렸다. AT&T -6.45%, Abbott -1.89%도 가입자·매출 전망을 소화했다. 실적이 이미 높아진 기대를 얼마나 더 충족하는지가 가격의 기준이었다.',
   '장후 메타는 초기에 상승했고 자료별로+2.1~3.65%가 관측됐다. 반면 램리서치는 장후 약5~7% 하락했다. 첫 반응과 이후 정규장 종가는 다르므로 메타가 발표 즉시 일관되게 급락했다고 재구성하지 않는다.',
   '미래에셋 FICC표는 미2년물4.81%(+3.20bp),10년물5.12%(+1.47bp),30년물5.41%(-0.54bp)를 제시했다. 20년물 입찰과 중동 긴장, 물가 경계가 겹쳤다. 응찰배율 개선만으로 장기채 조달비용 부담이 사라진 것은 아니었다.',
   'WTI는12월물97.15달러, Brent12월물108.82달러였다. 계약월이 바뀐 WTI를 전일11월물과 단순 비교하지 않는다. 재고 감소와 우회 수송 회복 기대, 장 후반 지정학 뉴스가 상반된 힘으로 작용했다.'
  ]},
  {no:'03',title:'국내 마감 — 큰 반등을 유지할 매수 기반이 부족했다',paragraphs:[
   '코스피는201.89p, 코스닥은28.66p 하락했다. 제공22일 마감자료의 지수 칸은 이전 날짜 수치를 반복하고 있어 종가 보도와 대조해 바로잡았다. 다른 관측과 과거 보고서는 소급 변경하지 않는다. <a href="https://m.etnews.com/20261022000405" target="_blank" rel="noopener noreferrer">22일 마감 보도</a>.',
   '미래에셋 KRX 마감 설명은 코스피 외국인+581억원, 기관-4,630억원이었다. 외국인 소폭 매수만으로 전체 반등을 지키지 못했다. 오전 현물·프로그램과 최종 집계, 시장별 수급을 혼합하지 않으며 미확보 코스닥 금액은 생성하지 않는다.',
   '신한 장중자료의 코스피5,628.9(-1.9%), 코스닥779.4(-1.6%)보다 최종 낙폭이 커졌다. 오전 메모리·장비·배터리 약세가 마감까지 부담이었다. 장중 종목 하락률을 종가로 바꿔 쓰지 않는다.',
   '미래에셋 마감은 배터리TOP10 ETF-6.36%, 소재ETF-7.35%를 제시했다. CATL 마진 충격에 Tesla 투자 전망 조정까지 겹쳤다. 배터리 수요·출하와 공급사의 이익·투자 유인은 같은 속도로 움직이지 않을 수 있다.',
   '반면 삼성E&A는 호실적과 자사주 취득·소각 소식에 마감자료 기준15.72% 올랐다. 건설ETF+3.80%, 카카오게임즈+7.30% 등 개별 회복도 있었다. 테마가 아니라 가시적인 이익·현금 환원이 차별화 요인이었다.',
   '기판·슈퍼커패시터·발전기 계약도 종목별 재료였지만 전체 기술주 매도를 흡수하지는 못했다. 계약 규모·기간·제품 믹스와 실제 수익 기여를 나눠야 한다. 신규 상장주와 작은 종목의 급등을 시장 유동성 회복의 증거로 일반화하지 않는다.'
  ]},
  {no:'04',title:'램리서치·메타 — 수요와 공급 능력, 회계이익과 현금의 다른 질문',paragraphs:[
   '램리서치 공식 발표의 분기 매출은82.19억달러, 조정EPS2.20달러였다. 다음 분기 매출은86±4억달러, 조정EPS2.33±0.15달러로 제시했다. 기록적 당기 실적과 앞으로의 기대 충족 여부는 별개였다. <a href="https://investor.lamresearch.com/2026-10-21-Lam-Research-Corporation-Reports-Financial-Results-for-the-Quarter-Ended-September-27%2C-2026" target="_blank" rel="noopener noreferrer">회사 실적·전망</a>.',
   '공급망 제약이 없었다면 전망이 더 높았을 수 있다는 컨콜 설명이 공식 검색 표시와 기관 보도에 제시됐다. 이는 최종 수요가 급감했다는 발표가 아니다. 수요가 있어도 장비 생산·부품·고객 가동 준비가 맞지 않으면 매출 인식이 늦어지는 실행 위험이었다.',
   '가격은 절대 실적이 아니라 이미 반영된 성장과 비교된다. 따라서 매출이 계속 늘어나는 기업도 기대한 상향 폭을 주지 못하면 배수가 낮아질 수 있다. 다만 당일 시장의 비공개 기대 분포는 확보되지 않아 모든 하락을 기대치 탓으로 정량 설명할 수는 없다.',
   '메타 공식 자료는 매출646억달러, 영업현금327.9억달러와 CapEx349.1억달러, FCF-21.2억달러를 제시했다. 연간CapEx 하단도 올라갔다. 현금 수입이 없어진 것이 아니라 투자 지출이 이를 웃돈 것이다. <a href="https://investor.atmeta.com/investor-news/press-release-details/2026/Meta-Reports-Third-Quarter-2026-Results/default.aspx" target="_blank" rel="noopener noreferrer">메타 공식 실적</a>.',
   '법률 관련 일회성 비용은 손익 해석에서 분리해야 하지만 이를 제거한다고 투자 후 현금 문제가 자동으로 없어지지 않는다. 회사별 FCF는 리스 처리 등 정의도 다를 수 있다. 매출 성장·광고 성과·일회성 비용·투자 재원을 각각 봐야 한다.',
   '전날 SpaceX·서버사의 개선이 AI 수익화 가능성을 보여줬다면 이번 발표는 그 성과가 모든 고객에게 동시에 나타나지는 않는다는 반례였다. 아직 한국22일 마감 시점에는 미국22일 종가 반응이 없었다. 장후 정보와 국내 매도를 연결하되 이후 급락을 미리 알고 있었다고 쓰지 않는다.'
  ]},
  {no:'05',title:'금통위 — 만장일치 동결은 관찰 시간 확보이지 긴축 종료가 아니다',paragraphs:[
   '한국은행은22일 기준금리3.00%를7명 모두 찬성해 유지했다. 앞선 두 차례 인상의 파급과 대외 위험을 살핀다는 결정이었다. 일부 기관이 예상했던 인상 소수의견은 나오지 않았다. <a href="https://www.bok.or.kr/portal/bbs/P0000559/view.do?menuNo=200690&nttId=11065823" target="_blank" rel="noopener noreferrer">한국은행 결정문</a>.',
   '동시에 성장 판단과 내년 물가 경계는 높아졌다. 동결 자체의 안도와 이후 추가 긴축 가능성이 함께 존재했다. 결정문에 남은 인상 시기·속도 판단을 곧바로 인하 전환으로 읽을 수 없는 이유다.',
   '총재는 선제 인상 덕분에 효과를 확인할 시간을 확보했다는 취지로 설명했다. 향후 특정 회의의 인상을 약속한 것은 아니다. 시점과 최종금리는 당시 공개자료로 확정할 수 없다.',
   '신한과 한화는 내년 상반기까지 두 차례 추가 인상·최종3.50% 전망을 유지했다. 사용자 자료의3.75%와 성장률3.7%·3.3%는 별도의 외삽 해석이다. 공식 성장 전망의 숫자 발표와 문구를 근거로 한 기관 예상은 구분한다.',
   '원화 강세는 수입물가와 구매력을 완충할 수 있지만 수출기업의 원화 환산 실적에는 부담일 수 있다. 수출 호조가 주식시장의 위험회피와 동시에 나타나면 금리·환율·주가가 단일 방향으로 반응하지 않는다.',
   '통화정책은 물가·주택·성장과 금융여건을 함께 본다. 주가 하락은 소비와 투자에 영향을 줄 수 있지만 하락했다는 이유만으로 즉시 인하할 수 있는 것은 아니다. 이 때문에 국내 주식의 실적 충격과 금통위 동결을 별도 경로로 해석한다.'
  ]},
  {no:'06',title:'국내 크레딧·인프라 — 투자 기회 옆에 재원 부담이 있다',paragraphs:[
   '한전 크레딧 자료는 현재의 대규모 부실보다2028년 사채발행 한도 정상화와 자본 확충의 속도를 문제 삼았다. 에너지 비용과 제한적인 이익 회복이 송전망 투자 재원을 제약할 수 있다는 기관 분석이다.',
   '자료의 약19.2조원 상환·자본 필요액은 미래 잔액과 한도 가정의 차이다. 현재 연체액이나 곧 발생할 채무불이행이 아니다. 한도 유예가 현실적이라는 전망 역시 입법·정책 결정이 완료됐다는 뜻은 아니다.',
   'AI 데이터센터는 건설·장비·전력 수요를 만들지만 투자 집행 주체의 재무 부담도 늘린다. 투자 총액을 공급사 매출과 발주사 이익에 동시에 더할 수 없다. 실제 임차인·전력·금융종결이 확인된 프로젝트와 계획만 있는 프로젝트의 수혜 시점도 다르다.',
   '비나텍과 혜인의 공급 계약, 삼성전기의 기판 협력은 물리적 인프라 수요의 근거다. 그러나 고객의 장기 지급 능력과 생산 일정이 맞아야 매출이 현금으로 전환된다. NDA·협상·시제품 공급과 양산 계약은 같은 강도의 증거가 아니다.',
   '차입이 SPV에 있어도 임대·구매·잔존가치 보증을 통해 손실이 운영사나 공급사로 돌아올 수 있다. 반대로 위험이 제한된 계약도 있다. 담보가 붙었다는 이유만으로 무위험이라고 보지 말고 회수 가능한 자산·보증·우선순위를 확인해야 한다.',
   '이 전달 경로는 주가 조정과 시스템 위기를 구분하는 기준이다. 지금 자료는 개별 기업의 투자·수급 제약을 보여주지만 금융기관 전체로 실제 손실이 확산됐다는 결론까지 뒷받침하지는 않는다. 불확실성을 전부 위기나 전부 기회로 환원하지 않는다.'
  ]},
  {no:'07',title:'에너지·유럽·소비 — 원유 가격 하나로 비용을 설명하기 어렵다',paragraphs:[
   '월스파의 EIA 인용은 미국 원유재고-310만배럴과 중간유분+170만배럴을 함께 전했다. 원유와 디젤의 재고 방향이 같지 않았다. 생산 차질·정제 처리·물류를 나눠야 제품 부족의 지속 여부를 판단할 수 있다.',
   '운임·보험료가 커지면 선물 기준유가와 실제 도착 원유 비용의 차이가 벌어진다. 지역·유종별 비교값을 세계 모든 정유사의 조달 단가로 쓰지 않는다. 높은 제품 마진도 비싼 원료·운임과 헤지 손익을 고려한 뒤 이익으로 연결된다.',
   '사우디 공관 인력 철수와 후티 공격은 지정학 부담을 높였다. 출국 명령·다른 지역 예정 조치·실제 시설 손실을 구분한다. 외교적 중재안 보도를 실제 휴전 체결이나 호르무즈 정상화로 바꿔 적지 않는다.',
   '프랑스10년물은21일5%를 넘어섰다는 보도가 있었다. 국채의 절대 금리와 독일 대비 스프레드는 다른 지표이며, 글로벌 금리 요인과 프랑스 재정·정치 위험을 나눠야 한다. 5%라는 숫자만으로 유로존 위기 재현을 선언하지 않는다.',
   '미국 소비·설비투자의 일부 강세와 유럽의 에너지 부담은 국가별 반응을 갈랐다. 한국에서도 수출과 내수·수입비용의 경로가 다르다. 산업 전체 수요보다 제품·지역·가격 협상력에 초점을 맞춰야 한다.',
   '22일 마감의 결론은 실적 안도가 곧 추세 복귀는 아니었다는 것이다. 이후 미국 본장과 다음 한국 거래일이 장후 경계를 어떻게 가격에 반영하는지는 다음 기록으로 남긴다. 아직 발표되지 않은 결과를 이 날짜의 판단에 넣지 않는다.'
  ]}
 ],
 watch:['램리서치 공급 제약과 실제 주문·출하 일정, 시장 기대의 차이','미국22일 본장의 메타·장비·전력주와 국채 반응','금통위 동결 이후 성장·물가 및 추가 인상 신호','반도체 외국인·기관 수급과 장중 반등의 지속성','건설 이익의 현금화·자사주 집행과 인프라 계약의 가동 일정','원유·제품 재고 및 유종별 도착가격·운임','프랑스 금리·스프레드와 미국 안전자산 수요','차입·리스·보증을 포함한 AI 고객의 지급 능력']
});
