 changes:{maintained:['실적 성장과 투자 후 현금·고객 지급 능력은 별도였다.','반도체 중심 반등만으로 넓은 수급 회복을 확인할 수 없었다.'],new:['램리서치 장후 약세와 메타 FCF 적자가 수익화 검증을 다시 자극.','한국은 전일 반등을 반납, 건설·개별 계약과 배터리·기술주 차별화.','기준금리3.00% 만장일치 동결, 전망의 소수의견과 다른 실제 결과.']},
 assessment:['기록적인 매출과 공급 병목은 공존한다. 램리서치 발표를 최종 수요 붕괴로 바꾸지 않는다.','동결은 시간을 확보한 결정이지 이익·수급·물가 위험의 해소가 아니다.'],
 implications:['실적과 전망·현금흐름을 구분하고 고객 투자 여력까지 본다.','안도 랠리의 지속성은 시장 폭과 실제 매수, 조달 조건으로 확인한다.'],
 conclusion:'코스피·코스닥은 전날 회복을 되돌렸다. 수익화 증거를 선호하는 시장에서 매출 성장만으로 투자 현금 부담을 덮기 어려웠다. 금통위는 동결했지만 긴축 종료를 확인하지 않았으며, 이후 미국 본장 반응은 다음 거래일의 정보다.'
