window.MARKET_LEDGER.daily['2026-10'].push({
 date:'2026-10-23',month:'2026년 10월',createdAt:'2026-10-23',updatedAt:'2026-10-23',
 title:'AI주 급락을 버틴 5,500선 — 국채로 피신한 자금, 반도체에 집중된 국내 반등',
 tags:['미국시황','램리서치충격','메타FCF','국채강세','기관매수','SolidigmIPO중단','좁은시장폭','AI계약위험'],
 lead:[
  '코스피는 장중 급락을 되돌려5,550.30(+0.30%)로 마감했지만 코스닥은751.69(-1.62%)로 하락했다. 미국22일 램리서치·메타 이후 반도체와 AI 인프라 투매가 먼저 아시아를 압박했다. 국내에서는 기관 매수와 Solidigm IPO 검토 중단에 따른 SK하이닉스 반등이 지수를 받쳤다.',
  '코스피 상승·하락172·720개, 코스닥405·1,247개로 내부 약세는 넓었다. 외국인은 코스피 약1조원을 팔았고 기관이 상당 부분을 흡수했다. 미국에서는 국채·방어주가 올랐으므로 모든 위험자산의 동반 붕괴도 아니었다. 주가 회복과 기업 신용·투자 정상화를 구분하는 것이 핵심이다.'
 ],
 report:[
  {no:'02',title:'미국 시황 — 램리서치·메타 충격은 기술주에서 컸고 방어주는 버텼다',paragraphs:[
   '미국22일 S&P500 7,663.43(-1.21%), Nasdaq 26,008.86(-2.60%), Nasdaq100 28,958.69(-2.90%)로 마감했다. SOX는10,731.98(-6.72%)로 급락했고 VIX는18.95(+13.61%)로 올랐다. Dow+0.02%, Russell2000+0.11%는 대조적이었다(미래에셋23일 브리핑).',
   '램리서치-11.76%, 메타-6.98%, Nvidia-4.40%, GE Vernova-10.64%, Tesla-3.08%였다. 반도체 장비의 출하 제약과 플랫폼 투자 현금 부담이 함께 가격에 반영됐다. 전력 인프라까지 투자 고객의 집행 능력을 다시 평가하는 흐름이었다.',
   'IT·커뮤니케이션은 각각3% 내렸지만 필수소비재+3.11%, 유틸리티+1.98%, 헬스케어+1.33%, 금융+1.18%였다. 동일가중지수 상승과 상승종목 다수라는 기관 설명도 있었다. 시총가중지수 하락을 미국 기업 전부의 침체 신호로 일반화할 수 없다.',
   'P&G+5.58%, Lockheed Martin+6.96%, Blackstone+8.38%, CSX+6.76%로 실적·방어 순환이 나타났다. AI 비중을 줄인 자금이 모두 현금을 택한 것이 아니라 다른 주식과 국채로 이동했다는 시장 구성의 변화다.',
   '미10년물은 약4.95~4.97%로5% 아래로 내려왔다. 자료의 요약·FICC표·사용자14:59ET 호가는 시각과 변동폭이 달라 하나의 확정 종가로 합치지 않는다. 국채 숏커버는 당시 기관의 해석이며 거래량을 분해해 확인한 값은 아니다.',
   'WTI12월물99.47달러(+2.18%), Brent113.17달러(+3.84%)로 유가는 오히려 올랐다. 그럼에도 국채금리가 내려갔다는 점은 이날 성장·현금 위험회피가 물가 경계를 압도했음을 시사한다. 금리 하락을 언제나 성장주 호재라고 볼 수 없는 사례다.'
  ]},
  {no:'03',title:'국내 마감 — 지수는 되돌렸지만 외국인과 시장 폭은 돌아오지 않았다',paragraphs:[
   '코스피는16.53p 상승했고 코스닥은12.41p 하락했다. 코스닥은 신한표751.70과 미래에셋·종가보도751.69가0.01p 달라 후자를 사용했다. 장중4%대 급락과 종가 양전은 다른 관측이다. <a href="https://newsway.co.kr/news/view?ud=2026102315464647334" target="_blank" rel="noopener noreferrer">23일 마감 보도</a>.',
   '신한 마감표 코스피 외국인-9,928억원, 기관+8,723억원, 개인+527억원이었다. 코스닥은 외국인-440억원, 기관-248억원, 개인+630억원이다. 기관의 코스피 흡수와 코스닥의 매수 공백을 구분한다. 범주 합계를 임의로 맞추지 않는다.',
   '코스피는 상승172개보다 하락720개가 훨씬 많았다. 코스닥도405·1,247개로 하락 우세였다. 5,500선 회복은 지수 방어의 성과지만 상승 참여도가 넓어진 것은 아니며 낙폭과대 종목의 회복이 보장된다는 뜻도 아니다.',
   '미래에셋 마감의 SK하이닉스+4.41%, 삼성전자+0.46%, 반도체TOP10 ETF+1.51%가 지수를 지지했다. Solidigm의 pre-IPO·IPO 검토 중단을 회사가 공식 발표했다. 중복상장 우려 완화와 실제 사업 성장·투자 재원 확보는 별개다. <a href="https://news.skhynix.com/en/fact-12/" target="_blank" rel="noopener noreferrer">하이닉스 공식 설명</a>.',
   '삼성바이오로직스는 노사 교섭·파업 연기 관련 안도로 강했고 건설도 실적을 바탕으로 선방했다. 폴더블폰·게임 등 개별 재료도 있었다. 다만 임상 변경 승인·출하 목표 상향·신작 기대를 매출과 허가 확정으로 바꾸지 않는다.',
   '은행ETF-2.78%와 KB금융-3.28%, 신한지주-2.43%는 반도체와 달랐다. 대출 연체율 상승이 기관 자료의 부담 요인이었으나 실제 손실 규모·차주 구성까지 확인한 것은 아니다. 전반적 신용경색과 일부 여신 건전성 악화를 동일시하지 않는다.'
  ]},
  {no:'04',title:'같은 금리 하락, 다른 주식 반응 — 할인율보다 현금흐름이 더 나빠질 때',paragraphs:[
   '이날 매도는 높은 금리 수준 자체보다 AI 투자가 얼마나 수익과 현금으로 돌아오는가에 집중됐다. 할인율이 내려가도 예상 현금흐름의 크기·시점·신뢰도가 더 악화되면 성장주 가격은 하락할 수 있다. 주식·채권의 상관은 지배적인 충격에 따라 달라진다.',
   '램리서치는 좋은 실적을 발표했지만 단기 공급 제약과 기대한 상향 여력이 쟁점이었다. 회사의 공식 다음 분기 전망은 증가를 가리켰다. 따라서 주가 급락을 곧 장비 주문 붕괴의 확정 증거로 읽는 것은 무리다.',
   '메타는 매출이 늘어도 투자 지출 이후 FCF가 적자로 바뀌었다. 본업의 현금 수입과 투자 후 잔여 현금은 다른 지표다. 법률비용을 조정한 이익과 자본지출 부담도 별도로 확인해야 한다.',
   '두 발표는 기존 CoreWeave 신용 경계와 만났지만 같은 사건은 아니다. 차입형 개발사의 조달 위험에서 장비 출하와 대형 플랫폼 투자까지 검증 범위가 넓어졌다. 이번에는 식별되는 실적 발표와 큰 업종 반응이 있어 별도 Casebook으로 기록한다.',
   'Jensen Huang의 강한 수요·자본 부족 발언은 비관론에 대한 반론이면서 제약을 인정하는 설명이었다. 고객이 서비스를 원한다는 주장과 운전자본·담보·전력 확보가 완료됐다는 사실은 다르다. 금융 메커니즘의 한도를 실제 실행된 대출 총액으로 쓰지 않는다.',
   '미국의 국채 강세·방어주 상승, 국내 기관의 메모리 매수는 위험 재배분의 경로였다. 정책 구제나 산업 전체 신용 정상화가 확인된 것은 아니다. 반등이 이어지려면 자금조달 조건과 실제 이익·가동 일정이 함께 안정돼야 한다.'
  ]},
  {no:'05',title:'AI 금융의 손실 귀속 — 계약 총액이 아니라 언제 누가 지급하는가',paragraphs:[
   '미래에셋 Economic Monthly는 큰 AI 투자 위험과 금융시스템 전체의 손실을 구분했다. 장기 임대·구매약정·보증으로 위험이 복잡하게 연결돼 있어 공시 부채만으로 노출을 읽기 어렵지만, 노출 총액이 전부 현재 손실은 아니다.',
   '상업 매출을 얻는 주체와 건설 자금을 대는 주체가 달라도 임차인의 지급 의무가 최종 상환 재원이 될 수 있다. 보증이 실행되면 손실은 다른 기업으로 이동한다. 담보의 재사용 가치와 계약 해지·회수 권리가 위험의 크기를 좌우한다.',
   '특히 고객 부진이 보증 제공자의 매출까지 낮추면 보증 능력도 약해진다. GPU 임대료·설비 가치가 함께 내려갈 때 담보 회수마저 악화되는 역방향 위험이다. 개별 계약을 따로 볼 때보다 공통 AI 수요에 노출된 정도가 중요해진다.',
   '보고서의 큰 가치 하락 스트레스에서도 초기 손실은 주주가 흡수하고 외부 전이는 제한적이라는 결과가 제시됐다. 임계 하락률은 계약·현금·회수 가정에 따른 모형 값이지 부도 확률이 아니다. 실제 산업 위기가 없다고 보증하는 결과도 아니다.',
   '사용자 월스트리트파인더의 핵심 질문도 같은 방향이다. 최종 고객의 서비스 지출은 변동하지만 인프라 지급 약정은 장기로 고정될 수 있다. IPO와 브리지는 시간을 벌어주지만 지속적인 영업현금을 대신하지 않는다.',
   'Ramp 지출 정체라는 BCA 인용과 같은 주 전월대비23% 증가라는 사이트 코멘트는 기간·표본·집계가 다를 수 있다. 사용량·토큰 가격·지출·서비스 매출을 구분하고 원계열 확인 전 어느 한쪽을 산업 수요의 결론으로 채택하지 않는다.'
  ]},
  {no:'06',title:'국채·환율·전망 — 안전자산 회귀와 장기 공급 부담을 구분한다',paragraphs:[
   '미국과 일본 국채·엔화의 강세는 AI와 지정학 위험에서 피신할 자산을 찾는 흐름이었다. 그러나 프랑스 채권은 재정·정치 프리미엄을 따로 부담했다. 모든 국채가 같은 위험을 가진다는 전제는 맞지 않는다.',
   '신한 FX는 달러 약세를 유도하는 미국 성장 기대 약화와 유로를 누르는 프랑스 불안이 상쇄된다고 봤다. 원화에는 수출기업 달러 매도가 지지 요인이었다. 국내 주식 외국인 매도와 원화 강세가 함께 나타날 수 있는 경로다.',
   '전날 한국은행의 동결은 추가 인상 가능성을 닫지 않았다. 그래서 위험회피 채권 매수와 물가·국채 공급의 중기 부담이 공존한다. 단기 금리 하락을 구조적인 채권 강세의 시작으로 단정하지 않는다.',
   '22일 발행 한화 주식전망은 ROE 저점과 PBR 인정이 핵심이라는 낙관적 반론을 제시했다. 목표8,500과 경로는 이익·장부가·환율 가정에 따른 기관 전망이다. 낮은 가격만으로 신용 할인이나 외국인 매도 위험이 사라지는 것은 아니다.',
   '신한은 주주환원 구체화 후 낙폭 둔화·횡보를 기본으로 보면서도 추가 긴축 경계를 유지했다. 서로 다른 기관의 전망을 합쳐 단일한 바닥 확인이나 가격 보장으로 쓰지 않는다. 관측된 반등과 미래 예상은 별도다.',
   '표지26일자의 FI2027 전망은 이번에 함께 받았지만22~23일 시장에 알려진 근거로 소급하지 않았다. 이 보고서는 자료를 보관하고 당시 발표된 금통위 리뷰를 이용했다. 새로운 자료의 입수와 과거 시장의 정보집합은 같지 않다.'
  ]},
  {no:'07',title:'에너지·유럽·중국 — 충격의 확산과 완충장치를 함께 본다',paragraphs:[
   '중국 주요 지수는23일 하락 출발 후 지수형 ETF 거래 증가와 함께 반등했다. 미래에셋 마감의 상해+0.89%, 심천+2.79%였다. 이 거래를 특정 정부기관의 확인된 개입으로 단정하지 않으며 한국 시장의 폭 부진과도 구분한다.',
   '유럽은 에너지 효율과 재정 지원·AI 수출이 성장 충격을 완충했다는 ECB 분석이 나왔다. 아일랜드 제외 GDP 비교는 전년 말 대비 수준 변화이지 연간 성장률이 아니다. 재정과 AI 수요의 지속성은 별도 위험이다. <a href="https://www.ecb.europa.eu/press/blog/date/2026/html/ecb.blog20261021~1c5ec8f223.en.html" target="_blank" rel="noopener noreferrer">ECB 성장 분석</a>.',
   'EUREP 확대는 적격 담보를 가진 해외 중앙은행의 유로 접근 준비를 진전시켰다. 안전망이 있다는 사실과 실제 인출·국채 매입이 증가했다는 사실은 다르다. 프랑스 위험에 대한 무조건적 구제로 해석할 수 없다. <a href="https://www.ecb.europa.eu/press/key/date/2026/html/ecb.sp261021~401d6c4b70.en.html" target="_blank" rel="noopener noreferrer">ECB 유동성 연설</a>.',
   'BIS의 사모신용 연구는 은행 유동성 규제가 대출을 은행 밖으로 이동시킬 수 있음을 보여준다. 은행 대출만으로 전체 기업 신용 공급을 판단하기 어렵다는 뜻이며 시스템 위험이 줄었다는 결론은 연구 범위 밖이다. <a href="https://www.bis.org/publications/bank-liquidity-regulation-and-growth-private-credit" target="_blank" rel="noopener noreferrer">BIS 연구</a>.',
   '에너지 충격은 직접 물가뿐 아니라 가격 조정·기대인플레이션을 통해 오래 남을 수 있다. 다만 BIS 관련 논문의 초기 전쟁 자료를9월CPI와 현재 유가를 반영한 최신 전망으로 사용하지 않는다. 유가 상승·주식 약세·금리 하락이 같은 날 나왔다고 물가 위험이 사라진 것도 아니다.',
   '현재의 결론은 충격의 범위가 넓어졌지만 반응은 균일하지 않았다는 것이다. 미국 방어주·국채와 국내 일부 대형주가 완충했으나 시장 폭·외국인·투자 재원은 여전히 약했다. 이후 실적과 지급 능력·가동 일정이 위험을 실제 손실로 바꾸는지 날짜별로 확인한다.'
  ]}
 ],
 watch:['램리서치 공급 병목의 해소와 다음 분기 출하·실제 실적','메타 이후 다른 하이퍼스케일러 FCF·리스·보증·투자 재원','코스피 기관 매수 지속성과 외국인 매도·코스닥 시장 폭','Solidigm 검토 중단 이후 대체 재원과 주주환원 실행','AI 약정의 현금 수취·지급 만기·담보·손실 귀속','국채 금리 하락이 신용 안정으로 연결되는지','미국23일 PMI·무디스 프랑스 평가 등 미발표 결과','원유 도착비용·정제품 재고와 원화 네고 수급']
});
