 assessment:['이번 충격은 절대 금리보다 현금흐름·기대 실현·실행 능력의 문제였다. 금리가 내려도 성장주가 약할 수 있었다.','코스피 양전은 방어의 성과지만 상승172/하락720과 외국인 매도가 정상화 해석을 제약한다.'],
