 conclusion:'5,500선은 회복했지만 시장 내부의 약세는 컸다. 램리서치·메타 이후 AI 투자 기대가 다시 조정됐고 안전자산·방어주로 자금이 이동했다. 기관과 일부 반도체의 회복을 전체 수급·신용의 복구로 확대하지 않는 판단이 필요하다.'
